(window.GIM_TS=window.GIM_TS||{})["Bava Batra.10"]={"from":240,"a":[["ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה שנאמר: \u0003\"\u0004על פי הגורל תחלק נחלתו \u0003בין רב למעט\"\u0004 (במדבר כו, נו), משמע שבין שבט מרובה באנשים ובין שבט מועט באנשים קיבלו חלק שווה.","\u0003ועוד\u0004 ראיה שארץ ישראל נתחלקה לשבטים, \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003עתידה ארץ ישראל שתתחלק לשלשה עשר שבטים,\u0004 לא כפי שהיה כשבאו תחילה לארץ, \u0003שבתחלה לא נתחלקה אלא לשנים עשר שבטים,\u0004 ששבט לוי לא קיבל דבר. ובענין חלוקתה של הארץ באותו זמן, מוסיפים: \u0003ולא נתחלקה אלא בכסף,\u0004 ששבט שקיבל חלק שווה יותר פיצה בכסף את השבט האחר, \u0003שנאמר: \"בין רב למעט\". אמר\u0004 \u0003ר' יהודה:\u0004 שטח בית \u0003סאה\u0004 תבואה \u0003ביהודה\u0004 היה יקר והיה \u0003שוה\u0004 במחירו לשטח בית \u0003חמש סאין בגליל. ו\u0004כן","\u0003לא נתחלקה\u0004 ארץ ישראל \u0003אלא בגורל, שנאמר: \"אך בגורל\u0004 יחלק את הארץ\u0003\"\u0004 (במדבר כו, נה). \u0003ולא נתחלקה אלא באורים ותומים, שנאמר: \"על פי הגורל\"\u0004 (במדבר כו, נו),","\u0003הא\u0004 \u0005[זו]\u0006 \u0003כיצד?\u0004 כיצד אפשר שיהיה גם על פי הגורל, וגם לפי האורים ותומים? \u0003אלעזר\u0004 הכהן הגדול, היה \u0003מלובש אורים ותומים, ויהושע וכל ישראל עומדים לפניו, וקלפי\u0004 (קופת גורל) \u0003של\u0004 שמות שנים עשר ה\u0003שבטים וקלפי\u0004 נוסף \u0003של תחומין\u0004 (איזורי ארץ ישראל) \u0003מונחין לפניו,\u0004","\u0003והיה מכוין\u0004 אלעזר \u0003ברוח הקדש\u0004 שנחה עליו \u0003ואומר\u0004 על פי האורים והתומים: בקלפי זה שמו של \u0003זבולן עולה\u0004 עכשיו בגורל, ו\u0003תחום עכו עולה עמו\u0004 בקלפי האחר. וכן היה, \u0003טרף\u0004 (עירבב) \u0003בקלפי של שבטים ועלה בידו\u0004 פתק שכתוב עליו \u0003זבולן,\u0004 ואז \u0003טרף בקלפי של תחומין ועלה בידו תחום עכו;\u0004","\u0003וחוזר\u0004 אלעזר \u0003ומכוין ברוח הקדש ואומר: נפתלי עולה ותחום גינוסר עולה עמו. טרף בקלפי של שבטים ועלה בידו נפתלי, טרף בקלפי של תחומין ועלה בידו תחום גינוסר. וכן כל שבט ושבט.\u0004","ומוסיפים עוד הבחנה בין חלוקת ארץ ישראל שהיתה לבין זו שתהיה לעתיד לבוא: \u0003ולא כחלוקה של עולם הזה חלוקה של עולם הבא\u0004 (לעתיד לבוא); \u0003העולם הזה, אדם\u0004 ש\u0003יש לו שדה לבן\u0004 (שדה תבואה) — \u0003אין לו שדה פרדס,\u0004 או אם יש לו \u0003שדה פרדס\u0004 — \u0003אין לו שדה לבן,\u0004 לפי שכל איזור מתאים לסוג אחר של גידולים, מצד האקלים וסוג האדמה שבו. אבל \u0003לעולם הבא, אין לך כל אחד ואחד\u0004 מישראל \u0003שאין לו\u0004 נחלה בארץ ישראל \u0003בהר ובשפלה ובעמק, שנאמר: \"שער ראובן אחד שער יהודה אחד שער לוי אחד\"\u0004 (יחזקאל מח, לא), לומר, שחלק כולם יהא שווה. ואותה חלוקה \u0003הקדוש ברוך הוא מחלק להן בעצמו, שנאמר: \"ואלה מחלקתם נאם ה'\"\u0004 (יחזקאל מח, כט).","עד כאן לשון הברייתא, ולענייננו, \u0003קתני מיהת\u0004 \u0005[שנה על כל פנים]:\u0006 \u0003\"שבתחלה לא נתחלקה אלא לשנים עשר שבטים\", שמע מינה\u0004 \u0005[למד מכאן]\u0006 \u0003לשבטים איפלוג\u0004 \u0005[נחלקה\u0006 הארץ\u0005]\u0006 ולא לפי גולגלות, ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד ממנה]\u0006 שכן היא.","ומעתה דנים בדברי הברייתא. \u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003עתידה ארץ ישראל שתתחלק לשלשה עשר שבטים.\u0004 ושואלים: \u0003אידך למאן\u0004 \u0005[\u0006החלק \u0005האחר,\u0006 השלושה עשר, \u0005למי]?\u0006 \u0003אמר רב חסדא:\u0004 זה יהיה חלק \u0003לנשיא,\u0004 כלומר, למלך, \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בחלוקה שלעתיד לבוא: \u0003\"והעבד העיר יעבדוהו מכל שבטי ישראל\"\u0004 (יחזקאל מח, יט), שהמלך, שהוא במובן מסויים משרת צרכי כל ישראל, הם יתנו לו אחוזה משלהם. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לאביי, אימא\u0004 \u0005[אמור]\u0006 שמה שנאמר \"יעבדוהו\" כוונתו \u0003רונגר בעלמא\u0004 \u0005[שכירות בלבד],\u0006 כלומר, שאין נותנים לו נחלה ממש, אלא שיש לו זכות לגבות שכר או מיסים מיוחדים! ומשיבים: \u0003לא סלקא דעתך\u0004 \u0005[\u0006יכול \u0005לעלות על דעתך\u0006 לומר כן\u0005],\u0006 \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר\u0006 שם\u0005]:\u0006 \u0003\"והנותר לנשיא מזה ומזה לתרומת הקדש ולאחזת העיר\",\u0004 כלומר, חלקו של הנשיא יהיה ממזרח וממערב לחלק תרומת הקודש ולאחוזת העיר. הרי שמדובר בחלק מוגדר של קרקע השייך לנשיא.","ועוד נאמר בברייתא: \u0003ולא נתחלקה\u0004 הארץ \u0003אלא לכספים, שנאמר: \"בין רב למעט\".\u0004 ודנים: \u0003למאי\u0004 \u0005[למה]\u0006 הכוונה? \u0003אילימא לשופרא וסניא\u0004 \u0005[אם תאמר ל\u0006ענין \u0005יפה וכעורה],\u0006 כלומר, קרקע משובחת או גרועה, שבעלי קרקע גרועה מקבלים מן האחרים פיצוי כספי, \u0003אטו בשופטני עסקינן\u0004 \u0005[וכי בשוטים עוסקים אנו]\u0006 שיסכימו לקבל קרקע פחותה תמורת כסף? \u0003אלא ל\u0004ענין של \u0003קרובה ורחוקה\u0004 שערכה של קרקע היה שונה לפי הקירבה לירושלים, והקרובים פיצו את הרחוקים בכסף.","ומעירים: ודבר זה, כיצד פיצו השבטים זה את זה, הרי שנוי \u0003כתנאי\u0004 \u0005[כ\u0006מחלוקת \u0005תנאים].\u0006 ששנינו, \u0003ר' אליעזר אומר: בכספים העלוה,\u0004 כלומר, בכספים שילמו השבטים שקיבלו נחלה יקרה יותר. \u0003ר' יהושע אומר: בקרקע העלוה,\u0004 שהשלימו את הפרש השווי על ידי תוספת קרקע.","ועוד שנינו בברייתא: \u0003ולא נתחלקה\u0004 ארץ ישראל \u0003אלא בגורל, שנאמר: \"אך בגורל\".\u0004 ובענין זה \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003\"אך בגורל\",\u0004 \"אך\" — לשון מיעוט הוא, לומר ש\u0003יצאו יהושע וכלב\u0004 (שאינם בכלל זה). ושואלים: \u0003למאי\u0004 \u0005[למה]\u0006 נאמר הדבר? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 ש\u0003לא שקול\u0004 \u0005[נטלו]\u0006 נחלה \u0003כלל,\u0004 \u0003השתא דלאו דידהו שקול\u0004 \u0005[עכשיו,\u0006 הרי, \u0005את\u0006 מה \u0005שאינו שלהם נטלו]\u0006 כפי ששנינו קודם (לעיל בבא בתרא קיח, ב), שקיבלו גם מנחלתם של המרגלים, \u0003דידהו מיבעיא\u0004 \u0005[שלהם\u0006 עצמם \u0005נצרכה\u0006 לומר\u0005]?\u0006 \u0003אלא\u0004 הכוונה היא, \u0003שלא נטלו בגורל, אלא על פי ה'\u0004 קיבלו נחלות מיוחדות; \u0003יהושע\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"על פי ה' נתנו לו את העיר אשר שאל את תמנת סרח בהר אפרים\"\u0004 (יהושע יט, נ)."],["אגב הזכרת המקום תמנת סרח מעירים: \u0003כתיב\u0004 \u0005[נאמר]\u0006 במקום אחד בתיאור קבורת יהושע: \u0003\"\u0004ויקברו אותו בגבול נחלתו בתמנת \u0003סרח\"\u0004 (יהושע כד, ל), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 במקום אחר: \u0003\"\u0004ויקברו אותו בגבול נחלתו בתמנת \u0003חרס\"\u0004 (שופטים ב, ט)! \u0003אמר\u0004 \u0003ר' אלעזר: בתחלה\u0004 היו \u0003פירותיה כחרס,\u0004 יבשים מאד, ונקרא שמה \"חרס\", \u0003ולבסוף\u0004 היו \u0003פירותיה מסריחין\u0004 מרוב שומנם, ונקרא שמה \"סרח\". \u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 באופן הפוך: \u0003בתחלה\u0004 היו פירותיה \u0003מסריחין,\u0004 שלא היו משתמרים, \u0003ולבסוף\u0004 היו \u0003כחרס,\u0004 שהיו משתמרים יפה.","\u0003כלב\u0004 לא זכה בנחלתו על פי הגורל, אלא על פי ה', \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויתנו לכלב את חברון כאשר דבר משה ויורש משם את שלשה בני הענק\"\u0004 (שופטים א, כ). ואגב הזכרת פסוק זה תוהים: כיצד ניתנה \u0003חברון\u0004 לכלב, והלא \u0003עיר מקלט הואי\u0004 \u0005[היתה],\u0006 והיתה שייכת לכהנים, כמפורש בספר יהושע (\"ולבני אהרן הכהן נתנו את עיר מקלט הרוצח את חברון...\", יהושע כא, יג)! \u0003אמר אביי: פרוורהא\u0004 \u0005[פרווריה]\u0006 שדותיה וכרמיה של העיר ניתנו לו, ולא העיר עצמה, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ואת שדה העיר ואת חצריה נתנו לכלב בן יפנה באחזתו\"\u0004 (יהושע כא, יב).","\u0003אחד הבן ואחד הבת\u0004 \u0003ב\u0004דין \u0003נחלה, אלא שהבן,\u0004 אם הוא בכור, \u0003נוטל פי שנים בנכסי האב ואינו נוטל פי שנים בנכסי האם. ו\u0004עוד הבדל: \u0003הבנות נזונות מנכסי האב\u0004 לאחר מותו, והן קודמות בכך לירושת הבנים, שהוא אחד מתנאי הכתובה של אימן, \u0003ואינן נזונות מנכסי האם,\u0004 אלא הבנים יורשים הכל, שדבר זה אינו מהתנאים המותנים ביניהם.","ומבררים את ששנינו במשנה: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"אחד הבן ואחד הבת לנחלה\"? אילימא דירתי כי הדדי\u0004 \u0005[אם תאמר ש\u0006הם \u0005יורשים זה כמו זה],\u0006 \u0003הא תנן\u0004 \u0005[הרי שנינו\u0006 במשנה\u0005]\u0006 במפורש: \u0003בן קודם לבת,\u0004 ואפילו \u0003כל יוצאי יריכו של בן קודמין לבת!\u0004","ונתנו \u0003סימן\u0004 לפתרונות שנתנו חכמים שונים לשאלה זו: \u0003\"נפשם\"\u0004 (נ חמן, פ פא, אש י, מר). \u0003אמר רב נחמן בר יצחק, הכי קאמר\u0004 \u0005[כך אמר,\u0006 התכוון התנא\u0005]:\u0006 \u0003אחד הבן ואחד הבת נוטלין בראוי\u0004 לבוא לידי אביהם, כמו \u0003במוחזק\u0004 כבר בידיו.","ותוהים: דבר זה אין צורך להשמיעו, \u0003הא נמי תנינא\u0004 \u0005[זו גם כן\u0006 כבר \u0005שנינו]:\u0006 \u0003בנות צלפחד נטלו שלשה חלקים בנחלה, חלק אביהן שהיה מיוצאי מצרים, וחלקו עם אחיו בנכסי חפר,\u0004 למרות שצלפחד מת בחיי חפר אביו, ועדיין לא הגיע חלקו בנחלת חפר לידיו!","\u0003ועוד\u0004 יש להקשות על הסבר זה, \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 המשך דברי המשנה: \"\u0003אלא\u0004 שהבן נוטל פי שנים מנכסי האב ואינו נוטל פי שנים מנכסי האם\"? והרי לא נשנתה קודם השוואה בין נכסי האב לנכסי האם, ואין לדברים כל קשר!","\u0003אלא אמר רב פפא,\u0004 יש לדחות פירוש זה ולומר הסבר אחר, ו\u0003הכי קאמר\u0004 \u0005[כך הוא אומר]:\u0006 \u0003אחד הבן ואחד הבת נוטלין חלק בבכורה,\u0004 כלומר, בחלק הנוסף שנטל אביהם כבכור בנכסי אביו.","ותוהים: \u0003הא נמי תנינא\u0004 \u0005[זו גם כן\u0006 כבר \u0005שנינו]:\u0006 \u0003ו\u0004החלק השלישי שנטלו בנות צלפחד — \u0003שהיה\u0004 צלפחד \u0003בכור נוטל שני חלקים\u0004 בנכסי חפר אביו, אחד ככל אח, וחלק נוסף כבכור! \u0003ועוד\u0004 יש להקשות גם לפירוש זה, \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"אלא\"?\u0004 שלא התייחס תחילה כלל לירושת האם!","\u0003אלא אמר רב אשי הכי קאמר\u0004 \u0005[כך הוא אומר]:\u0006 \u0003אחד בן בין הבנים ואחד בת בין הבנות, אם אמר\u0004 האב \u0003\"\u0004בני פלוני \u0003יירש כל נכסי\"\u0004 — \u0003דבריו קיימין,\u0004 והוא הדין אם אמר \"בתי פלונית תירש כל נכסי\", כשאין שם אלא בנות.","ושואלים: \u0003כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי]\u0006 נאמר דבר זה, \u0003כר' יוחנן בן ברוקא? הא קתני לה לקמן\u0004 \u0005[הרי שנה אותה לפנינו,\u0006 בהמשך\u0005],\u0006 \u0003ר' יוחנן בן ברוקא אומר: אם אמר\u0004 שמוריש כל נכסיו \u0003על מי שראוי ליורשו\u0004 — \u0003דבריו קיימין,\u0004 אבל אם אמר זאת \u0003על מי שאינו ראוי ליורשו\u0004 — \u0003אין דבריו קיימין,\u0004 אלא היורשים זוכים בירושתו!","\u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003קא סתם לן\u0004 \u0005[סתמה לנו\u0006 המשנה פה\u0005]\u0006 \u0003כ\u0004דעת \u0003ר' יוחנן בן ברוקא,\u0004 להורות שהלכה כמותו — הרי סתם זה אינו מועיל, כי \u0003סתם ואחר כך מחלוקת היא,\u0004 שהרי ר' יוחנן בן ברוקה חולק כבמשנה להלן על חכמים, \u0003ו\u0004כלל הוא, ש\u0003סתם ואחר כך מחלוקת\u0004 — \u0003אין הלכה כסתם!\u0004","\u0003ועוד\u0004 יש לשאול גם לדרך זו: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"אלא\"\u0004 שנאמר כאן? הרי לא דובר בתחילה בירושת האם כלל!","\u0003אלא אמר מר בר רב אשי, הכי קאמר\u0004 \u0005[כך הוא אומר]:\u0006 \u0003אחד הבן ואחד הבת שוין\u0004 בנחלה \u0003בנכסי האם ובנכסי האב,\u0004 כלומר, אין הבדל בין נכסי האב והאם, הן לענין הבן והן לענין הבת, \u0003אלא\u0004 בדברים אלו: \u0003שהבן\u0004 אם הוא בכור \u0003נוטל פי שנים בנכסי האב, ואינו נוטל פי שנים בנכסי האם.\u0004 וכן שהבנות נוטלות מזונות קודם לירושת הבנים בנכסי האב ולא בנכסי האם.","ועוד בענין הבכורה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 מה שנאמר בירושת הבכור \u0003\"\u0004כי את הבכור... יכיר \u0003לתת לו פי שנים\"\u0004 (דברים כא, יז), הכוונה היא \u0003פי שנים כאחד,\u0004 כלומר, שהוא מקבל כפליים מאשר כל אחד מן האחים. ויש לדון בדבר זה: \u0003אתה אומר\u0004 שהוא מקבל \u0003פי שנים כאחד\u0004 האחים, \u0003או אינו\u0004 מקבל \u0003אלא פי שנים בכל הנכסים\u0004 כולם? כלומר, פי שנים מכל שאר אחיו יחד, שהוא נוטל שני שליש מכל נכסי אביו, ואחיו האחרים מתחלקים בשליש הנותר. \u0003ודין הוא,\u0004 ויש לדון בדבר זה ולטעון:"],["הרי \u0003חלקו\u0004 של בכור בירושת האב, פעמים שהוא \u0003עם\u0004 אח \u0003אחד, ו\u0004פעמים \u0003חלקו עם חמשה\u0004 אחים, והואיל והתורה אינה מחלקת בין המקרים יש להשוות את הדין בכל המצבים, ולומר: \u0003מה חלקו עם אחד\u0004 — מקבל \u0003פי שנים כאחד\u0004 כמו אותו אח, \u0003אף חלקו עם חמשה\u0004 — \u0003פי שנים כ\u0004של \u0003אחד\u0004 האחים!","ואפשר לטעון גם להיפך, \u0003או כלך\u0004 (לך) \u0003לדרך זו,\u0004 לצד השני, ואמור: \u0003חלקו עם אחד וחלקו עם חמשה, מה חלקו עם אחד\u0004 — \u0003פי שנים בכל הנכסים,\u0004 שכן הוא נוטל שני שליש מכלל הנכסים, \u0003אף חלקו עם חמשה\u0004 יהיה \u0003פי שנים בכל הנכסים!\u0004","\u0003תלמוד לומר: \"והיה ביום הנחילו את בניו\"\u0004 (דברים כא, טז), ובכתוב זה, שאינו נחוץ במקומו, \u0003התורה ריבתה נחלה אצל אחין,\u0004 ומכאן יש להכריע: \u0003הא\u0004 \u0005[הרי]\u0006 \u0003אין עליך לדון כלשון האחרון אלא כלשון הראשון;\u0004 ומביאים ראיות נוספות לדין זה,","\u0003ואומר\u0004 הכתוב: \u0003\"ובני ראובן בכור ישראל כי הוא הבכור ובחללו יצועי אביו נתנה בכרתו לבני יוסף בן ישראל ולא להתיחש לבכרה\"\u0004 (דברי הימים א ה, א), \u0003ו\u0004כן \u0003אומר\u0004 הכתוב: \u0003\"כי יהודה גבר באחיו ולנגיד ממנו והבכרה ליוסף\"\u0004 (דברי הימים א ה, ב), ומעתה נלמד:","\u0003נאמרה\u0004 לשון \u0003\"בכורה\" ליוסף\u0004 בפסוקים אלה (\"נתנה בכורתו לבני יוסף\", \"הבכורה ליוסף\") \u0003ונאמרה\u0004 לשון \u0003\"בכורה\" לדורות\u0004 בפרשת נחלת הבכור (\"לו משפט הבכורה\", דברים כא, יז), ונלמד מזה על זה: \u0003מה בכורה האמורה ליוסף\u0004 משמעה שקיבל \u0003פי שנים כאחד\u0004 מן האחים, \u0003אף בכורה האמורה לדורות\u0004 — \u0003פי שנים כאחד; ו\u0004הרי כך","\u0003אומר\u0004 הכתוב: \u0003\"ואני נתתי לך שכם אחד על אחיך אשר לקחתי מיד האמורי בחרבי ובקשתי\"\u0004 (בראשית מח, כב). ומביאים מה שאמרו חכמים על פסוק זה: \u0003וכי בחרבו ובקשתו לקח? והלא כבר נאמר:\u0004 \u0003\"\u0004בך צרינו ננגח בשמך נבוס קמינו, \u0003כי לא בקשתי אבטח וחרבי לא תושיעני\"\u0004 (תהלים מד, ה–ז)! \u0003אלא, \"חרבי\"\u0004 — \u0003זו תפלה, \"קשתי\"\u0004 — \u0003זו בקשה.\u0004","ודנים בדברי הברייתא, ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"ואומר\"?\u0004 מדוע יש צורך להביא ראיות נוספות? ומסבירים: לאחר שהובאה הראיה מן הפסוק \"והיה ביום הנחילו את בניו\", כאילו ממשיכה הברייתא ואומרת: \u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 כי \u0003האי\u0004 \u0005[\u0006פסוק \u0005זה]\u0006 \u0003לכ\u0004דברי \u0003ר' יוחנן בן ברוקא הוא דאתא\u0004 \u0005[שבא],\u0006 לומר שיש לאב רשות להנחיל לכל אחד מבניו את כל רכושו, ואין ללמוד מכאן דבר זה — \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה מהפסוק האחר: \u0003\"ובני ראובן בכור ישראל...\u0004 נתנה בכורתו לבני יוסף\", ומכך שבני יוסף נטלו שני חלקים כשני אחים, יש ללמוד לדורות, בגזירה שווה מ\"בכורתו\" \"בכורה\".","\u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003\"בכרה\" מ\"בכורתו\" לא גמרינן\u0004 \u0005[אין אנו למדים]\u0006 ואין כאן גזירה שווה, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ולמד גזירה שווה מ\"בכורה\" — \u0003\"והבכרה ליוסף\".\u0004","\u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003יוסף גופיה\u0004 \u0005[עצמו]\u0006 \u0003ממאי\u0004 \u0005[ממה,\u0006 מנין יודע אתה\u0005]\u0006 ש\u0003פי שנים כאחד הוה\u0004 \u0005[היה]?\u0006 \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]:\u0006 \u0003\"ואני נתתי לך שכם אחד על אחיך\"\u0004 (בראשית מח, כב), כלומר, חלק אחד נוסף.","על ראיה זו \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לאביי: אימא\u0004 \u0005[אמור]\u0006 ש\"שכם אחד\" משמעו שהוא מוסיף לו \u0003דיקלא בעלמא\u0004 \u0005[דקל בלבד]\u0006 או דבר קטן כלשהו, אבל לא חלק שלם! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003עליך,\u0004 כלומר, כדי להוציא מסברה שכזו, \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"אפרים ומנשה כראובן ושמעון יהיו לי\"\u0004 (בראשית מח, ו), לומר שנוספה ליוסף נחלת שבט שלם, כאחד מבני יעקב.","\u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003ר' חלבו מר' שמואל בר נחמני: מה ראה יעקב שנטל בכורה מראובן ונתנה ליוסף?\u0004 ותוהים: \u0003מה ראה?!\u0004 הרי טעם הדבר מפורש הוא — \u0003\"ובחללו יצועי אביו\u0004 נתנה בכורתו לבני יוסף\u0003\"\u0004 (דברי הימים א ה, א) \u0003כתיב\u0004 \u0005[נאמר]!\u0006 \u0003אלא\u0004 כך היתה השאלה: \u0003מה ראה שנתנה ליוסף\u0004 דווקא ולא לאחר?","אמר לו ר' שמואל בר נחמני לר' חלבו: \u0003אמשול לך משל, למה הדבר דומה?\u0004 — \u0003לבעל הבית שגדל יתום בתוך ביתו, לימים העשיר אותו יתום ואמר: אהניהו לבעל הבית מנכסי.\u0004 וכך הואיל ובמשך שנים פירנס יוסף את יעקב במצרים, מצא יעקב בזמן ההנחלה מקום להחזיר לו טובה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' חלבו: \u0003ואי לאו\u0004 \u0005[ואם לא]\u0006 ש\u0003חטא ראובן, לא מהני ליה\u0004 \u0005[היה\u0006 יעקב \u0005מהנה לו]\u0006 ל\u0003יוסף ולא מדעם\u0004 \u0005[דבר]?\u0006 וודאי לא זאת עיקר הסיבה.","\u0003אלא\u0004 האם \u0003ר' יונתן רבך לא כך אמר,\u0004 ופירש ענין זה באופן הזה: \u0003ראויה היתה בכורה לצאת מרחל, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"אלה תלדות יעקב יוסף\"\u0004 (בראשית לז, ב), שיוסף היה עיקר תולדותיו של יעקב, \u0003אלא שקדמתה לאה ברחמים\u0004 (בתפילה), \u0003ומתוך צניעות שהיתה בה ברחל החזירה הקדוש ברוך הוא לה\u0004 את הבכורה.","ומבארים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"קדמתה לאה ברחמים\"?\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ועיני לאה רכות\"\u0004 (בראשית כט, יז), ויש לשאול: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"רכות\"? אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003רכות ממש,\u0004 שהיו נוטפות דמעות, וכי \u0003אפשר\u0004 שלכך הכוונה? והרי אפילו \u0003בגנות בהמה טמאה לא דבר הכתוב, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"מן הבהמה הטהורה ומן הבהמה אשר איננה טהרה\"\u0004 (בראשית ז, ח), שהאריך הכתוב באומרו \"אשר איננה טהורה\" על מנת שלא לכתוב על הבהמה במפורש שהיא טמאה, \u0003בגנות צדיקים דבר הכתוב? אלא אמר\u0004 \u0003ר' אלעזר:\u0004 יש להבין \"רכות\" במשמעות ארוכות, לומר \u0003שמתנותיה ארוכות,\u0004 שהמתנות שניתנו לשבטי לאה, כהונה (ללוי) ומלכות (ליהודה), נמשכות לדורות, שלא כמתנות שניתנו לשבטי רחל.","\u0003רב אמר: לעולם רכות ממש,\u0004 שהיו דומעות, \u0003ולא גנאי הוא לה אלא שבח הוא לה. שהיתה שומעת על פרשת דרכים בני אדם שהיו\u0004 באים מארץ ישראל והיו \u0003אומרים: שני בנים יש לה לרבקה\u0004 אחות לבן, \u0003שתי בנות יש לו ללבן, גדולה\u0004 שבבנות תינשא \u0003לגדול\u0004 שבבנים \u0003וקטנה לקטן.\u0004","\u0003והיתה יושבת על פרשת דרכים ומשאלת\u0004 (שואלת): \u0003גדול מה מעשיו?\u0004 והיו אומרים לה: \u0003איש רע הוא מלסטם\u0004 (גוזל) \u0003בריות,\u0004 וכששאלה: \u0003קטן מה מעשיו?\u0004 היו עונים לה: \u0003\"איש תם ישב אהלים\"\u0004 (בראשית כה, כז), \u0003והיתה בוכה\u0004 על שתצטרך להינשא לרשע זה \u0003עד שנשרו ריסי עיניה\u0004 מחמת הבכי, וזהו השבח במה שעיניה רכות.","ומעירים: \u0003והיינו דכתיב\u0004 \u0005[וזהו שנאמר]:\u0006 \u0003\"וירא ה' כי שנואה לאה\"\u0004 (בראשית כט, לא), \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"שנואה\"? אילימא\u0004 \u0005[אם תאמר]\u0006 שהיתה \u0003שנואה ממש,\u0004 וכי \u0003אפשר\u0004 הדבר? והרי \u0003בגנות בהמה טמאה לא דבר הכתוב, בגנות צדיקים דבר הכתוב? אלא ראה הקדוש ברוך הוא ששנואין מעשה עשו בפניה\u0004 והוא הענין של \"שנואה\" — \u0003\"ויפתח את רחמה\"\u0004 (בראשית כט, לא).","וממשיכים בביאור דברי ר' יונתן: \u0003ומאי\u0004 \u0005[ומה]\u0006 \u0003צניעות היתה בה ברחל? דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויגד יעקב לרחל כי אחי אביה הוא וכי בן רבקה הוא\"\u0004 (בראשית כט, יב), ותמוה הדבר: וכי אחי אביה הוא? \u0003והלא בן אחות אביה הוא! אלא\u0004 יש להבין \"אח\" האמור כאן במובן אחר. וכך היו מדברים ביניהם, \u0003אמר לה: מינסבת\u0004 \u0005[תינשאי]\u0006 \u0003לי? אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003אין\u0004 \u0005[כן],\u0006 \u0003מיהו\u0004 \u0005[ואולם]\u0006 \u0003אבא\u0004 שלי \u0003רמאה\u0004 \u0005[רמאי]\u0006 \u0003הוא, ולא יכלת ליה\u0004 \u0005[תוכל לו].\u0006","\u0003אמר לה: מאי רמאותיה\u0004 \u0005[מהי רמאותו]?\u0006 במה הוא יכול לרמותני? \u0003אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003אית\u0004 \u0005[יש]\u0006 \u0003לי אחתא דקשישא מינאי\u0004 \u0005[אחות שמבוגרת ממני]\u0006 \u0003ולא מנסבא לי מקמה\u0004 \u0005[ישיא אותי לפניה].\u0006 \u0003אמר לה: אחיו אני ברמאות,\u0004 והוא מה שאמר שאחי אביה הוא. \u0003אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003ומי שרי להו לצדיקי לסגויי ברמאותא\u0004 \u0005[והאם מותר להם לצדיקים להתהלך,\u0006 להתנהג \u0005ברמאות]?\u0006 ענה לה: \u0003אין\u0004 \u0005[כן],\u0006 פעמים מותר הדבר, ככתוב \u0003\"עם נבר תתבר ועם עקש תתפל\"\u0004 (שמואל ב כב, כז). ומה עשה כדי שלא ירמה אותו לבן? \u0003מסר לה\u0004 לרחל \u0003סימנין\u0004 שידע על ידם שהיא זו שמשיאים לו לאשה.","\u0003כי קא מעיילי לה ללאה\u0004 \u0005[כאשר הכניסוה את לאה]\u0006 לחופה, \u0003סברה\u0004 \u0005[חשבה]\u0006 רחל: \u0003השתא מיכספא אחתאי\u0004 \u0005[עכשיו תתביש אחותי]\u0006 כאשר יגלה יעקב את המירמה. \u0003מסרתינהו ניהלה\u0004 \u0005[מסרה אותם,\u0006 את הסימנים, \u0005לה].\u0006 \u0003והיינו דכתיב\u0004 \u0005[וזהו שנאמר]:\u0006 \u0003\"ויהי בבקר והנה הוא לאה\"\u0004 (בראשית כט, כה), ויש לתמוה: \u0003מכלל\u0004 הדברים אתה למד ש\u0003עד השתא\u0004 \u0005[עכשיו]\u0006 \u0003לאו\u0004 \u0005[לא]\u0006 \u0003לאה היא?! אלא, מתוך סימנים שמסר לה יעקב לרחל ומסרתה ללאה, לא הוה ידע לה\u0004 \u0005[היה יודע בה]\u0006 \u0003עד ההיא שעתא\u0004 \u0005[אותה שעה]\u0006 שראה אותה בבוקר.","\u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003אבא חליפא קרויא מר' חייא בר אבא: בכללן\u0004 של יעקב ומשפחתו הבאים למצרים \u0003אתה מוצא שבעים\u0004 (\"כל הנפש לבית יעקב הבאה מצרימה שבעים\". בראשית מו, כז), \u0003בפרטן\u0004 כשאתה מונה את שמותיהם (בראשית מו, כז) \u0003אתה מוצא שבעים חסר אחד! אמר ליה\u0004 \u0005[לו]:\u0006 \u0003תאומה היתה עם דינה, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ואת דינה בתו\"\u0004 (בראשית מו, טו). ש\"את\" לשון ריבוי ותוספת היא, והיא המשלימה למספר השבעים. חזר והקשה לו: \u0003אלא מעתה,\u0004 לפי זה, גם \u0003תאומה היתה עם בנימן, דכתיב\u0004 \u0005[שנאמר]:\u0006"],["\u0003\"ואת בנימין אחיו בן אמו\"\u0004 (בראשית מג, כט). שגם בפסוק זה נאמר \"את\", וכאמור שהיא לשון ריבוי לאחות נוספת! הוסיף ו\u0003אמר\u0004 לו: \u0003מרגלית טובה היתה בידי ואתה מבקש לאבדה ממני,\u0004 כלומר, יש לי טעם יקר ערך לדבר זה, ולא רציתי לאומרו לך עד עכשיו, \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר\u0004 \u0003ר' חמא בר חנינא:\u0004 מי שמשלים את מספר בני יעקב שבאו למצרים \u0003זו יוכבד, שהורתה\u0004 (הריונה) היה \u0003בדרך\u0004 מארץ כנען למצרים, \u0003ולידתה בין החומות\u0004 שבמצרים, \u0003שנאמר: \"אשר ילדה אתה ללוי במצרים\"\u0004 (במדבר כו, נט), לומר: \u0003לידתה במצרים, ואין הורתה במצרים.\u0004","ועוד בעניינים אלו \u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003ר' חלבו מר' שמואל בר נחמני, כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"ויהי כאשר ילדה רחל את יוסף\u0004 ויאמר יעקב אל לבן שלחני ואלכה אל מקומי ולארצי\u0003\"\u0004 (בראשית ל, כה), \u0003מאי שנא כי אתיליד\u0004 \u0005[מה שונה,\u0006 השתנה \u0005כאשר נולד]\u0006 \u0003יוסף,\u0004 שדווקא אז אמר יעקב ללבן שהוא רוצה ללכת, ולא לפני כן? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003ראה יעקב אבינו\u0004 בנבואה \u0003שאין זרעו של עשו נמסר\u0004 (נתפס) \u0003אלא ביד זרעו של יוסף, שנאמר: \"והיה בית יעקב אש ובית יוסף להבה ובית עשו לקש\u0004 ודלקו בהם ואכלום","\u0003\"\u0004(עובדיה א, יח), והרי ברח יעקב לארם מפני עשו שרצה להורגו, ומעתה שוב לא יוכל עשו לפגוע בו. \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 ר' חלבו: הרי נאמר במלחמה על הגדוד העמלקי שכבש את צקלג (והוא זרעו של עשו): \u0003\"ויכם דוד מהנשף ועד הערב למחרתם\"\u0004 (שמואל א ל, יז), ודוד הריהו משבט יהודה. משמע שגם בני יהודה יש בכוחם להכות את זרעו של עשו! \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' שמואל בר נחמני: \u0003דאקריך נביאי\u0004 \u0005[מי שהקרה,\u0006 לימד, \u0005אותך\u0006 את ספרי \u0005נביאים]\u0006 \u0003לא אקריך כתובי\u0004 \u0005[הקרה אותך כתובים],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בכתובים: \u0003\"בלכתו\u0004 (של דוד) \u0003אל צקלג נפלו עליו ממנשה עדנה ויוזבד וידיעאל ומיכאל ויוזבד ואליהוא וצלתי ראשי האלפים אשר למנשה\"\u0004 (דברי הימים א יב, כא), ובני מנשה מזרע יוסף הם. נמצא שגם מלחמת דוד בעמלק בצקלג היתה בידי בני יוסף.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב יוסף: \"ומהם מן בני שמעון הלכו להר שעיר אנשים חמש מאות ופלטיה ונעריה ורפיה ועזיאל בני ישעי בראשם, ויכו את שארית הפלטה לעמלק וישבו שם עד היום הזה\"\u0004 (דברי הימים א ד, מב), משמע שגם בני שמעון יש בכוחם להכות את בני עשו! \u0003אמר רבה בר שילא: ישעי מבני מנשה אתי\u0004 \u0005[בא],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ובני מנשה חפר וישעי\".\u0004","ושבים לדון בדין הבכור, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003הבכור\u0004 אם היה של כהן, \u0003נוטל פי שנים בזרוע ובלחיים ובקיבה\u0004 הניתנות לכהן מכל בהמת חולין שנשחטה, \u0003ו\u0004כן נוטל הבכור (אף של ישראל) \u0003במוקדשין\u0004 של האב, \u0003ובשבח ששבחו\u0004 (השביחו, עלו בערכם) ה\u0003נכסים\u0004 של הירושה \u0003לאחר מיתת אביהן\u0004 שלו ושל אחיו.","\u0003כיצד,\u0004 באיזה מקרה נוטל בשבח? \u0003הניח להן אביהן פרה\u0004 שהיתה \u0003מוחכרת ומושכרת ביד אחרים, או שהיתה רועה באפר\u0004 (באחו, בשדה) \u0003וילדה\u0004 — \u0003בכור נוטל\u0004 אף בוולד \u0003פי שנים, אבל\u0004 אם הבנים \u0003בנו בתים ונטעו כרמים\u0004 לאחר מות אביהם — \u0003אין בכור נוטל\u0004 בשבח \u0003פי שנים\u0004 לפי שאין זה שבח ששבחו נכסי האב, אלא דבר שהם עצמם עשוהו.","ודנים בפרטי הדברים: \u0003האי\u0004 \u0005[זה]\u0006 \u0003הזרוע והלחיים והקיבה היכי דמי\u0004 \u0005[כיצד בדיוק מדובר]?\u0006 \u0003אי דאתי\u0004 \u0005[אם שבאו]\u0006 כבר מתנות אלה \u0003לידי אבוהון\u0004 \u0005[אביהם],\u0006 \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 שהבכור יורש פי שנים בכל אשר לו, ואין צורך לומר דבר זה, \u0003ואי\u0004 \u0005[ואם]\u0006 מדובר במקרה ש\u0003לא אתי\u0004 \u0005[באו]\u0006 עדיין המתנות \u0003לידי אבוהון\u0004 \u0005[אביהם],\u0006 הלא \u0003ראוי הוא, ו\u0004דין הוא ש\u0003אין הבכור נוטל\u0004 פי שנים \u0003בראוי\u0004 כפי שהוא נוטל \u0003במוחזק!\u0004","ומשיבים: \u0003הכא\u0004 \u0005[כאן]\u0006 מדובר בזרוע לחיים וקיבה שלא הגיעו לידי אביהם, ובכל זאת אין זה ראוי אלא מוחזק, לפי ש\u0003במכירי כהונה עסקינן\u0004 \u0005[עוסקים אנו],\u0006 באנשים שהיו רגילים לתת את מתנותיהם לכהן זה דווקא, \u0003ו\u0004כגון \u0003דאשתחיט\u0004 \u0005[שנשחטה]\u0006 הבהמה \u0003בחיי דאבוהון\u0004 \u0005[אביהם],\u0006 \u0003וקסבר\u0004 \u0005[וסבור]\u0006 חכם זה: \u0003מתנות\u0004 כהונה \u0003שלא הורמו\u0004 (הופרשו) \u0003כמי שהורמו דמו\u0004 \u0005[נחשבות],\u0006 ולכן יש לבן הבכור בהם דין ירושת בכור.","ועוד שואלים: \u0003מוקדשין\u0004 ששנינו בברייתא שנוטל בהם הבכור פי שנים — \u0003לאו דידיה נינהו\u0004 \u0005[לא שלו הם],\u0006 שהרי משעה שמקדיש אדם בהמה לה', שוב אין הבהמה נחשבת כקניינו של המקדיש, אלא רכוש שמים היא, ואם כן מה שייך בה דין ירושה?","ומשיבים: מדובר כאן \u0003בקדשים קלים,\u0004 כגון קרבן שלמים, \u0003ואליבא\u0004 \u0005[ועל פי שיטתו]\u0006 של \u0003ר' יוסי הגלילי\u0004 ש\u0003אמר: ממון בעלים הוא; דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 נאמר בדיני הגוזל חפץ של חבירו ונשבע לשקר, שמביא אשם גזילות: \u0003\"ומעלה מעל בה'\u0004 וכיחש בעמיתו\u0003\"\u0004 (ויקרא ה, כא), \u0003לרבות\u0004 זה הנשבע על \u0003קדשים קלים\u0004 של חבירו, לפי \u0003שהן\u0004 בעיקרם \u0003ממון בעלים,\u0004 אלו \u0003דברי\u0004 \u0003ר' יוסי הגלילי.\u0004 ולשיטתו, כיון שקדשים קלים נחשבים ממון בעלים — יש בהם דין ירושה, והבכור נוטל בהם פי שנים.","ועוד שנינו בברייתא: \u0003הניח להן אביהן פרה מוחכרת ומושכרת ביד אחרים, או שהיתה רועה באפר, וילדה\u0004 — \u0003בכור נוטל בה פי שנים.\u0004 ותוהים: \u0003השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 \u0003מוחכרת ומושכרת, דלאו ברשותא דמרה דידהו קיימא\u0004 \u0005[\u0006למרות \u0005שלא ברשות בעליה שלה\u0006 היא \u0005עומדת],\u0006 שהרי היא מצויה עתה בידי השוכר — \u0003אמרת שקיל\u0004 \u0005[אומר אתה\u0006 ש\u0005נוטל]\u0006 הבכור פי שנים בשבח, אם היתה \u0003רועה באפר,\u0004 שלא יצאה מרשות האב, \u0003מיבעיא\u0004 \u0005[נצרכה\u0006 לומר\u0005]\u0006 שנוטל?","ומשיבים: \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה השמיע לנו],\u0006 שפרה \u0003מוחכרת ומושכרת\u0004 הנזכרת כאן, היא \u0003דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003רועה באפר\u0004 הנזכרת אף היא כאן; \u0003מה רועה באפר\u0004 מדובר ב\u0003שבחא דממילא קא אתי\u0004 \u0005[שבח שמאליו הוא בא],\u0006 \u0003ולא קא חסרי\u0004 \u0005[חסרים]\u0006 \u0003בה\u0004 האחים \u0003מזונא\u0004 \u0005[\u0006\u0005מזון],\u0006"],["\u0003אף מוחכרת ומושכרת\u0004 מדובר ב\u0003שבחא דממילא קא אתי\u0004 \u0005[שבח שמאליו הוא בא],\u0006 במקרה ש\u0003לא חסרי\u0004 \u0005[חסרים]\u0006 \u0003בה\u0004 האחים \u0003מזוני\u0004 \u0005[מזונות],\u0006 אלא התנו שהשוכר או החוכר הוא המאכיל את הבהמה.","עד כאן עסקנו בביאור הברייתא. ומעירים: \u0003מני\u0004 \u0005[\u0006שיטת \u0005מי היא]\u0006 ברייתא זו? — שיטת \u0003רבי היא; דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אין בכור נוטל פי שנים ב\u0004כל \u0003שבח ששבחו נכסים לאחר מיתת אביהן.\u0004 ואילו \u0003רבי אומר, אומר אני: בכור נוטל פי שנים בשבח ששבחו נכסים\u0004 מעצמם \u0003לאחר מיתת אביהן, אבל לא בשבח שהשביחו יתומים לאחר מיתת אביהן.\u0004 כיצד?","— אם \u0003ירשו שטר חוב\u0004 שהיו אחרים חייבים לאביהם — \u0003בכור נוטל פי שנים\u0004 בכספי אותו חוב לכשייגבה, \u0003יצא עליהן שטר חוב\u0004 שהיה מוטל על האב — \u0003בכור נותן\u0004 בפרעון אותו חוב \u0003פי שנים. ואם אמר\u0004 הבכור: \u0003איני נותן\u0004 עבור חלק יתר של בכורה, \u0003ואיני נוטל\u0004 את חלק הבכורה — \u0003רשאי\u0004 לעשות כן.","ומבררים ברייתא זו: \u0003מאי טעמייהו דרבנן\u0004 \u0005[מה טעמם של חכמים]\u0006 שהם סבורים שאין הבכור נוטל פי שנים בכל שבח ששבחו נכסים לאחר מות האב? \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"לתת לו פי\u0004 \u0003שנים\"\u0004 (דברים כא, יז) שחלק הבכורה \u0003\"מתנה\" קרייה רחמנא\u0004 \u0005[קראה אותו התורה],\u0006 ומכאן יש ללמוד: \u0003מה\u0004 דבר הניתן ב\u0003מתנה,\u0004 אינו ניתן אלא \u0003עד דמטיא\u0004 \u0005[שהגיע]\u0006 תחילה \u0003לידיה\u0004 \u0005[לידו]\u0006 של הנותן, \u0003אף חלק בכורה\u0004 אינו ניתן לבכור \u0003עד דמטיא לידיה\u0004 \u0005[שמגיעה לידו]\u0006 של האב תחילה, ומה שלא היה בידו בחייו, אינו נותן לבכור.","\u0003ורבי,\u0004 שסבור שבכור נוטל חלק בכורה בשבח ששבחו נכסים מאליהם לאחר מות האב, \u0003אומר, אמר קרא\u0004 \u0005[הכתוב]\u0006 בדין הבכור: \u0003\"פי שנים\", מקיש\u0004 (משווה) כתוב זה \u0003חלק בכורה לחלק פשוט\u0004 שבשניהם זוכה הבכור, \u0003מה חלק פשוט אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003לא מטא לידיה\u0004 \u0005[הגיע לידו]\u0006 של האב הבכור יורש אותו, \u0003אף חלק בכורה, אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003לא מטא לידיה\u0004 \u0005[הגיע לידו]\u0006 של האב זוכה בו הבכור.","ושואלים: \u0003ורבנן נמי הכתיב\u0004 \u0005[וחכמים גם כן, הרי נאמר]:\u0006 \u0003\"פי שנים\"\u0004 ללמד שדינם כאחד! ומשיבים: \u0003ההוא, למיתבא ליה אחד מצרא\u0004 \u0005[אותו\u0006 ביטוי נאמר ללמד שיש \u0005לתת לו\u0006 לבכור את שני חלקיו \u0005על\u0006 \u0005מצר,\u0006 גבול, \u0005אחד\u0006 זה בצד זה\u0005]\u0006 ולא לתת אותם בשני מקומות נפרדים.","ומן הצד האחר שואלים: \u0003ורבי נמי\u0004 \u0005[גם כן]\u0006 \u0003הכתיב\u0004 \u0005[הרי נאמר]:\u0006 \u0003\"לתת לו\"!\u0004 ומשיבים: \u0003ההוא\u0004 \u0005[אותו]\u0006 ביטוי בא ללמדנו דין אחר המופיע בברייתא, \u0003שאם\u0004 הבכור \u0003אמר: איני נוטל\u0004 חלק בכורה \u0003ואיני נותן\u0004 חלק כפול בפרעון חוב של האב — \u0003רשאי.\u0004 שכיון שהיא כמתנה — יכול לסרב לקבל אותה.","ובבירורה המדוייק של המחלוקת \u0003אמר רב פפא: דיקלא ואלים\u0004 \u0005[דקל שנעשה עבה\u0006 יותר\u0005]\u0006 לאחר מות האב, והרי הוא משובח יותר, \u0003ארעא ואסיק שירטון\u0004 \u0005[אדמה שהעלתה שירטון,\u0006 סחף\u0005]\u0006 והושבחה בכך — \u0003דכולי עלמא לא פליגי דשקיל\u0004 \u0005[הכל אינם חלוקים ש\u0006הבכור \u0005נוטל]\u0006 פי שנים בתוספת השבח. \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 — \u0003בחפורה והוה שובלי\u0004 \u0005[בשחת שנעשתה שיבולים],\u0006 או \u0003שלופפי והוו תמרי\u0004 \u0005[פרחי דקלים שנעשו תמרים],\u0006 \u0003דמר סבר\u0004 \u0005[שחכם זה,\u0006 רבי, \u0005סבור]:\u0006 \u0003שבחא דממילא\u0004 \u0005[שבח שמעצמו\u0006 הוא\u0005]\u0006 זה, ונוטל בו הבכור חלק בכורה, \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 חכמים, \u0005סבור]:\u0006 \u0003אישתני\u0004 \u0005[השתנה]\u0006 ונעשה דבר חדש, ואין זה בכלל מה שהיה לאביהם תחילה.","ובענין ההלכה למעשה \u0003אמר רבה בר חנא אמר\u0004 \u0003ר' חייא:\u0004 מי ש\u0003עשה\u0004 ופסק בענין זה \u0003כדברי רבי\u0004 — \u0003עשה,\u0004 דינו דין, ואינו בטל. עשה \u0003כדברי חכמים\u0004 — \u0003עשה.\u0004"],["ומסבירים: \u0003מספקא ליה\u0004 \u0005[מסופק לו\u0006 לר' חייא\u0005]\u0006 \u0003אי\u0004 \u0005[אם]\u0006 הכלל הקובע ש\u0003הלכה כרבי מחבירו\u0004 משמעו: דווקא מחבירו \u0003ולא מחביריו,\u0004 וכאן הרי חולקים עליו חכמים, ואם כן אין הלכה כמותו. \u0003או\u0004 שמא \u0003הלכה כרבי מחבירו\u0004 משמעו: \u0003ואפילו מחביריו.\u0004 וכיון שאין בידו להכריע, הריהו משאיר את ההכרעה בידי כל דיין, וכל פסיקה שהיא אינה בטילה.","\u0003אמר רב נחמן אמר רב: אסור לעשות כדברי רבי,\u0004 ומסבירים: \u0003קא סבר\u0004 \u0005[סבור הוא]\u0006 רב: \u0003הלכה כרבי מחבירו ולא מחביריו.\u0004","\u0003ורב נחמן דידיה\u0004 \u0005[שלו\u0006 עצמו\u0005]\u0006 \u0003אמר\u0004 שלא כדברים שאמר משמו של רב: \u0003מותר לעשות כדברי רבי.\u0004 ומסבירים: \u0003קא סבר\u0004 \u0005[סבור הוא]\u0006 \u0003הלכה כרבי מחבירו ואפילו מחביריו.\u0004","ועוד דעה בענין זה, \u0003אמר רבא: אסור לעשות כדברי רבי, ואם עשה\u0004 — \u0003עשוי,\u0004 ומסבירים: \u0003קא סבר\u0004 \u0005[סבור הוא]\u0006 \u0003מטין איתמר\u0004 \u0005[נאמר].\u0006 שלא נקבעה הלכה גמורה כדברי חכמים, אבל סיכמו כי הנטייה היא כדעת חכמים, ובמקרה כזה אף שלכתחילה יש לעשות כדבריהם, מכל מקום אם עשה כדברי רבי — אין מחזירים את הדין. ומעירים: אף מן האמור במדרש ההלכה, אין קביעת הלכה ברורה בענין זה, אם כרבי או כחכמים, שהרי תלוי הדבר בנוסחים שונים.","שכן \u0003תני\u0004 \u0005[שנה]\u0006 \u0003רב נחמן\u0004 ברייתא \u0003ב\u0004תוך \u0003שאר ספרי דבי\u0004 \u0005[הספרים של בית\u0006 מדרשו\u0005]\u0006 של \u0003רב,\u0004 שהוא הכינוי למדרשי ההלכה (הנוספים על תורת כהנים לספר ויקרא) על הכתוב בדין הבכור \"לתת לו פי שנים בכל אשר ימצא לו\" (דברים כא, יז): \u0003\"בכל אשר ימצא לו\"\u0004 לאב — \u0003פרט לשבח שהשביחו יורשין לאחר מיתת אביהן,\u0004 שבזה אין הבכור נוטל פי שנים. ומכאן יש להסיק: \u0003אבל שבח ששבחו נכסים\u0004 מעצמם \u0003לאחר מיתת אביהן\u0004 — \u0003שקיל\u0004 \u0005[נוטל],\u0006 \u0003ומני\u0004 \u0005[ו\u0006שיטת \u0005מי היא]\u0006 ברייתא זו? שיטת \u0003רבי היא.\u0004","ומצד אחר \u0003תני\u0004 \u0005[שנה]\u0006 \u0003רמי בר חמא\u0004 \u0003ב\u0004תוך \u0003שאר ספרי דבי\u0004 \u0005[הספרים של בית\u0006 מדרשו\u0005]\u0006 של \u0003רב\u0004 בנוסח אחר: \u0003\"בכל אשר ימצא לו\"\u0004 — \u0003פרט לשבח ששבחו נכסים לאחר מיתת אביהן,\u0004 שאין הבכור נוטל בשבח זה פי שנים. ויש ללמוד מכאן: \u0003וכל שכן שבח שהשביחו יורשין לאחר מיתת אביהן\u0004 ש\u0003לא שקיל\u0004 \u0005[נוטל],\u0006 \u0003ומני\u0004 \u0005[ו\u0006שיטת \u0005מי היא]?\u0006 — שיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 \u0003היא.\u0004","\u0003אמר רב יהודה אמר שמואל: אין בכור נוטל פי שנים במלוה.\u0004 ומבררים: \u0003למאן\u0004 \u0005[ל\u0006שיטת \u0005מי]\u0006 נאמרה הלכה זו? \u0003אילימא לרבנן\u0004 \u0005[אם תאמר ל\u0006שיטת \u0005חכמים],\u0006 \u0003השתא שבחא דאיתיה ברשותיה\u0004 \u0005[עכשיו,\u0006 הרי \u0005שבח\u0006 ששבחו נכסים, \u0005ש\u0006הנכס עצמו \u0005ישנו ברשותו]\u0006 של האב \u0003אמרי רבנן\u0004 \u0005[אומרים חכמים]\u0006 ש\u0003לא שקיל\u0004 \u0005[נוטל]\u0006 הבכור פי שנים באותו שבח, \u0003מלוה מבעיא\u0004 \u0005[נצרכה\u0006 לומר\u0005]\u0006 שאינו נוטל? שהרי המילוה אינו נמצא ברשות האב בזמן מותו, ורק ראוי הוא שיגיע לידיו בזמן הפרעון.","\u0003אלא\u0004 ודאי אמר שמואל כן \u0003ל\u0004שיטת \u0003רבי,\u0004 שאף שלדעתו, בשבח ששבחו נכסים נוטל הבכור פי שנים, במילוה, שלא היה ברשות האב — אינו נוטל.","ומקשים: \u0003ואלא\u0004 לפי זה \u0003הא דתניא\u0004 \u0005[\u0006הלכה \u0005זו ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003ירשו\u0004 הבנים \u0003שטר חוב\u0004 מאביהם — \u0003בכור נוטל פי שנים\u0004 בפרעון החוב \u0003בין במלוה בין ברבית, מני\u0004 \u0005[\u0006שיטת \u0005מי היא]?\u0006 \u0003לא\u0004 שיטת \u0003רבי ולא\u0004 שיטת \u0003רבנן\u0004 \u0005[חכמים]!\u0006","ומגיעים למסקנה: אלא \u0003לעולם\u0004 מה שאמר שמואל שאין הבכור נוטל פי שנים במילוה, \u0003ל\u0004שיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 הוא, \u0003ואצטריך\u0004 \u0005[והוצרך]\u0006 הדבר להיאמר לשיטת חכמים, לפי שאינו מובן מאליו, כי \u0003סלקא דעתך אמינא\u0004 \u0005[עולה על דעתך לומר]:\u0006 \u0003מלוה, כיון דנקיט שטרא\u0004 \u0005[שמחזיק\u0006 המלוה \u0005שטר\u0006 חוב בידו\u0005]\u0006 — \u0003כמאן דגביא דמיא\u0004 \u0005[כמי שגבוי\u0006 הוא \u0005נחשב]\u0006 ואף חכמים מודים שיש בו חלק כפול לבכור, ועל כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שמואל, שאין המילוה נחשב כמוחזק בידי האב, ואין הבכור נוטל בו פי שנים.","ועוד בענין זה \u0003שלחו מתם\u0004 \u0005[משם\u0006 מארץ ישראל\u0005]\u0006 פסק הלכה זה: \u0003בכור נוטל פי שנים במלוה אבל לא ברבית,\u0004 שאם האב הלוה כסף לגוי בריבית, סכום המילוה עצמו יש בו חלק כפול לבכור, אבל הריבית הריהי בגדר ראוי בלבד.","ושואלים: \u0003למאן\u0004 \u0005[ל\u0006שיטת \u0005מי]\u0006 פוסקים הם? \u0003אילימא לרבנן\u0004 \u0005[אם תאמר ל\u0006שיטת \u0005חכמים],\u0006 \u0003השתא שבחא דאיתיה ברשותיה\u0004 \u0005[עכשיו,\u0006 הרי \u0005שבח\u0006 ששבחו נכסים מעצמם, \u0005ש\u0006הנכס עצמו \u0005ישנו ברשותו\u0006 של האב\u0005],\u0006 — \u0003אמרי רבנן דלא שקיל\u0004 \u0005[\u0006\u0005אומרים חכמים שאינו נוטל],\u0006 \u0003מלוה\u0004 שאינו ברשותו של האב \u0003מבעיא\u0004 \u0005[נצרכה\u0006 לומר\u0005]\u0006 שאינו נוטל בו חלק בכורה?","\u0003אלא\u0004 ודאי הלכו \u0003ל\u0004שיטת \u0003רבי.\u0004 ושואלים: \u0003ול\u0004דעת \u0003רבי, ברבית לא\u0004 נוטל חלק בכורה? \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005],\u0006 \u0003רבי אמר: בכור נוטל פי שנים בין במלוה בין ברבית!\u0004","אלא \u0003לעולם\u0004 לשיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 \u0003היא\u0004 הלכה זו שהורו חכמי ארץ ישראל, \u0003ו\u0004לדעתם סבורים חכמים כי \u0003מלוה כמאן דגביא דמיא\u0004 \u0005[כמי שגבוי נחשב]\u0006 אבל הריבית לא.","ומסופר, \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בר רב לרבינא: איקלע\u0004 \u0005[הזדמן]\u0006 \u0003אמימר לאתרין ודריש\u0004 \u0005[למקומנו ודרש]:\u0006 \u0003בכור נוטל פי שנים במלוה אבל לא ברבית. אמר ליה\u0004 \u0005[לו]:\u0006 \u0003נהרדעי לטעמייהו\u0004 \u0005[חכמי נהרדעא\u0006 הולכים \u0005לשיטתם],\u0006 אמימר הולך בענין זה כשיטתו של רב נחמן, שהיה כמוהו מחכמי נהרדעא.","ש\u0003אמר רבה:\u0004 יתומים ש\u0003גבו קרקע\u0004 בחוב אביהם — \u0003יש לו\u0004 לבכור, חלק כפול בהם, \u0003גבו מעות\u0004 — \u0003אין לו. ורב נחמן אמר: גבו מעות\u0004 — \u0003יש לו, גבו קרקע\u0004 — \u0003אין לו.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרבה: לדידך קשיא\u0004 \u0005[ל\u0006שיטתך \u0005שלך קשה],\u0006 \u0003ל\u0004שיטת \u0003רב נחמן קשיא\u0004 \u0005[קשה];\u0006 ומסביר: \u0003לדידך קשיא\u0004 \u0005[ל\u0006שיטתך \u0005שלך קשה]:\u0006"],["\u0003מאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה]\u0006 גביית \u0003מעות\u0004 ש\u0003לא\u0004 מקבל בהם הבכור פי שנים — משום \u0003דלאו הני מעות שבק אבוהון\u0004 \u0005[שלא\u0006 את \u0005המעות הללו הניח אביהם],\u0006 אלא רק התחייבות של הלווה לפרוע לו. ואם כן, גביית \u0003קרקע נמי\u0004 \u0005[גם כן]\u0006 — \u0003לאו הא קרקע שבק אבוהון\u0004 \u0005[לא\u0006 את \u0005הקרקע הזו הניח\u0006 להם \u0005אביהם\u0006 כשמת\u0005],\u0006 שהרי היתה רק משועבדת לו, ויכול היה הלווה לשלם חובו בקרקע אחרת, או לשלם לו מעות!","\u0003ועוד, הא את\u0004 \u0005[הרי אתה]\u0006 \u0003הוא\u0004 ש\u0003אמרת: מסתבר טעמא דבני מערבא\u0004 \u0005[הטעם של בני ארץ ישראל]\u0006 בענין נכדה שהיתה ראויה לירש את סבתה, ומתה הסבתא לפניה. ורצה בעלה של הנכדה לרשת אותה סבתא במקום אשתו, ואמרו חכמי ארץ ישראל שאינו נוטל משום שלגבי אשתו לא היו נכסים אלו אלא בגדר של ראוי בלבד, לפי \u0003דאי קדים\u0004 \u0005[שאם\u0006 היתה \u0005מקדימה]\u0006 ה\u0003סבתא וזבנא\u0004 \u0005[ומוכרת]\u0006 — \u0003זבינה זביני\u0004 \u0005[מכירתה מכר]\u0006 ואין הבעל יורש בראוי כבמוחזק, ואף כאן — הרי יכול היה הלווה למכור קרקע זו שגבו ממנו היתומים, ולכן לא היתה אלא ראוי! זה מה שקשה לרבה.","וגם \u0003לרב נחמן קשיא\u0004 \u0005[קשה]:\u0006 \u0003מאי שנא\u0004 \u0005[מה שונה]\u0006 \u0003קרקע\u0004 שגבו ש\u0003לא\u0004 נוטל הבכור פי שנים? משום \u0003דלאו הא קרקע שבק אבוהון\u0004 \u0005[שלא\u0006 את \u0005הקרקע הזו הניח אביהם],\u0006 שהרי יכול היה הלווה לפרוע לו במעות, \u0003מעות נמי\u0004 \u0005[גם כן]\u0006 \u0003לאו הני מעות שבק אבוהון\u0004 \u0005[לא\u0006 את \u0005המעות הללו הניח אביהם]!\u0006","\u0003ועוד, הא\u0004 \u0005[הרי]\u0006 \u0003אמר רב נחמן אמר רבה בר אבוה: יתומים שגבו קרקע בחובת אביהן\u0004 — \u0003בעל חוב\u0004 של אביהם \u0003חוזר וגובה מהן\u0004 קרקע זו, לפי שהיא משועבדת לו, ככל נכס שהיה אביהם קונה בחייו. ונמצא שאף רב נחמן עצמו סבור שקרקע משועבדת דינה כדבר המוחזק בידי המלוה, ומדוע אומר הוא לגבי בכור שאם גבו קרקע אין לו בה חלק בכורה?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבה לאביי: \u0003לא לדידי קשיא\u0004 \u0005[ל\u0006שיטתי \u0005שלי קשה]\u0006 \u0003ולא ל\u0004שיטת \u0003רב נחמן קשיא\u0004 \u0005[קשה],\u0006 שכן \u0003טעמא דבני מערבא\u0004 \u0003קאמרינן\u0004 \u0005[\u0006את \u0005הטעם של בני ארץ ישראל אומרים אנו]\u0006 ונחלקנו בהסברת הדברים לפי שיטתם, \u0003ולן לא\u0004 \u0003סבירא לן\u0004 \u0005[ו\u0006אולם \u0005אנו\u0006 עצמנו, \u0005איננו סבורים כן]\u0006 כדעת בני ארץ ישראל.","כיון שהוזכר הענין, שואלים: \u0003מאי\u0004 \u0005[מהו]\u0006 אותו ענין של \u0003סבתא\u0004 שהוזכר מקודם? \u0003דההוא\u0004 \u0005[ש\u0006אדם \u0005אחד]\u0006 ש\u0003אמר להו\u0004 \u0005[להם]\u0006 לעומדים עליו בשעת מיתה:"],["\u0003\"\u0004את כל \u0003נכסי\u0004 אני נותן \u0003לסבתא ובתרה לירתאי\"\u0004 \u0005[ואחריה,\u0006 אחרי מותה, יינתנו הנכסים \u0005ליורשיי]\u0006 שהם יירשו אותה, ולא יורשיה. ונפטר אותו איש. \u0003הויא ליה ברתא דהוה נסיבא\u0004 \u0005[היתה לו בת\u0006 יחידה \u0005שהיתה נשואה],\u0006 \u0003שכיבא\u0004 \u0005[מתה]\u0006 אותה בת \u0003בחיי בעלה ובחיי\u0004 ה\u0003סבתא, בתר דשכיבא\u0004 \u0005[אחרי שמתה]\u0006 ה\u0003סבתא, אתא\u0004 \u0005[בא]\u0006 ה\u0003בעל\u0004 של אותה בת \u0003קא תבע\u0004 \u0005[\u0006ו\u0005היה תובע]\u0006 את הנכסים כיורש של אשתו,","\u0003אמר רב הונא:\u0004 מה שאמר אביה \u0003\"לירתי\"\u0004 \u0005[ליורשי],\u0006 כוונתו: \u0003ואפילו לירתי ירתי\u0004 \u0005[ליורשי יורשי],\u0006 וכיון שהבעל יורש את אשתו יש לו זכות בנכסים. \u0003ורב ענן אמר: \"לירתי\"\u0004 \u0005[ליורשי]\u0006 משמעו: \u0003ולא לירתי ירתי\u0004 \u0005[ליורשי יורשי].\u0006","\u0003שלחו מתם\u0004 \u0005[משם\u0006 מארץ ישראל\u0005]:\u0006 \u0003הלכתא כוותיה\u0004 \u0005[הלכה כשיטתו]\u0006 של \u0003רב ענן, ו\u0004אולם \u0003לאו מטעמיה\u0004 \u0005[לא מטעמו]\u0006 לא מן הטעם שהוא נתן. ומפרטים: \u0003הלכתא כוותיה\u0004 \u0005[הלכה כשיטתו]\u0006 של \u0003רב ענן\u0004 — ש\u0003בעל לא ירית\u0004 \u0005[יורש]\u0006 נכסים אלה. \u0003ולאו מטעמיה\u0004 \u0005[ולא מטעמו],\u0006 ש\u0003אילו רב ענן סבר\u0004 \u0005[סבור]:\u0006 \u0003אף על גב דהוה ליה ברא לברתיה\u0004 \u0005[אף על פי ש\u0006אם \u0005היה לה בן לבתו]\u0006 \u0003לא ירית\u0004 \u0005[\u0006היה הבן \u0005יורש],\u0006 שהרי אמר רק \"ליורשי\" ולא ליורשי יורשי. \u0003ולא היא,\u0004 אין הדבר כן, ש\u0003אילו הוה ליה ברא לברתיה ודאי ירית\u0004 \u0005[היה לה בן לבתו ודאי\u0006 היה \u0005יורש],\u0006 \u0003ובעל היינו טעמא דלא ירית\u0004 \u0005[זהו הטעם שאינו יורש]\u0006 — \u0003משום דהוה ליה\u0004 \u0005[ש\u0006ממון זה \u0005הריהו]\u0006 רק בגדר של \u0003ראוי\u0004 שלא היה ברשות האשה בחייה, \u0003ואין הבעל,\u0004 כשהוא יורש את אשתו, \u0003נוטל בראוי\u0004 להגיע ליד האשה \u0003כ\u0004דרך שהוא נוטל \u0003במוחזק\u0004 בידה.","ותוהים: \u0003מכלל\u0004 הדברים אתה למד ש\u0003רב הונא\u0004 שפסק שהבעל יורש, \u0003סבר\u0004 \u0005[סבור]\u0006 כי \u0003בעל נוטל בראוי כבמוחזק?!\u0004","\u0003אמר\u0004 \u0003ר' אלעזר, דבר זה נפתח בגדולים ונסתיים בקטנים\u0004 בלשון ענוה אמר, שרב הונא שהוא מן הגדולים אמר בתחילה דבר זה, והוא, ר' אלעזר, ישלים ויסביר את דבריו, שטעמו הוא משום ש\u0003כל האומר\u0004 לגבי ירושה או מתנה: \"נכסי נתונים לך ו\u0003אחריך\u0004 לפלוני\", \u0003כאומר \"\u0004נכסי נתונים לפלוני \u0003מעכשיו\" דמי\u0004 \u0005[נחשב].\u0006 אלא שבינתיים יש לראשון זכות ליהנות מהם, ומשום כך נמצא שהנכסים הללו היו כמוחזקים בידי האשה עוד בחייה (מכח הצוואה) ולכן הבעל יורש אותם.","\u0003אמר רבה: מסתברא טעמא דבני מערבא\u0004 \u0005[מסתבר הטעם של בני ארץ ישראל]\u0006 שהנכסים שהיו ביד הזקנה נחשבו כראוי ביד הנכדה, ולא כמוחזק, \u0003דאי קדים\u0004 \u0005[ש\u0006הרי \u0005אם היתה מקדימה]\u0006 ה\u0003סבתא וזבנא\u0004 \u0005[ומוכרת]\u0006 את הנכסים לפני מותה — \u0003זבינה זביני\u0004 \u0005[מכירתה\u0006 היתה \u0005מכר]\u0006 ואז לא היו הנכסים הללו מגיעים כלל לבת. ואם כן, בחיי הבת היו רק ראויים לבת ולא מוחזקים, ואין הבעל יורש בראוי.","לסיכומה הכולל של ההלכה בעניינים אלו \u0003אמר רב פפא, הלכתא\u0004 \u0005[הלכה]:\u0006 \u0003אין הבעל נוטל בראוי כבמוחזק. ואין הבכור נוטל בראוי כבמוחזק. ואין הבכור נוטל פי שנים במלוה, בין שגבו קרקע בין שגבו מעות,\u0004"],["\u0003ומלוה שעמו,\u0004 הלוואה שלוה אותו בכור מאביו, בזה \u0003פלגי\u0004 \u0005[חולקים]\u0006 את חלק הבכורה. שכיון שהכסף בפועל מוחזק בידי הבכור לא ברור לנו כיצד יש להתייחס לכסף זה, האם כמוחזק או כראוי, ולכן חולקים הבכור ואחיו ביניהם את חלק הבכורה מספק.","ובענין שדנו בו לעיל, שהבכור אינו נוטל פי שנים בשבח שהשביחו האחים את הנכסים לאחר מות האב, \u0003אמר רב הונא אמר רב אסי: בכור שמיחה\u0004 — \u0003מיחה,\u0004 כלומר, זכותו של הבכור לומר לאחיו שאין הוא מסכים שישביחו את הנכסים קודם חלוקה, ואם בכל זאת השביחו — הריהו מקבל חלק כפול גם בשבח.","\u0003אמר רבה: מסתבר טעמיה\u0004 \u0005[טעמו]\u0006 הלכה זו של \u0003רב אסי\u0004 — \u0003ב\u0004מקרה שכאשר מת האב היו נכסי הירושה \u0003ענבים,\u0004 שהינם עדיין על הגפן ומחה הבכור באחיו שלא ישביחום, והם עברו על דבריו \u0003ובצרום\u0004 (קטפו אותם), וכן ב\u0003זיתים\u0004 שהינם עדיין על העץ \u0003ומסקום\u0004 (קטפו אותם), שלא נשתנו מכמות שהיו, \u0003אבל\u0004 אם \u0003דרכום\u0004 את הענבים ועשו מהם יין, הרי אף שמחה בהם — \u0003לא\u0004 יטול פי שנים בשבח. \u0003ורב יוסף אמר: אפילו דרכום\u0004 נוטל פי שנים בשבח.","ועל דברים אלה תוהים: גם אם \u0003דרכום?!\u0004 הלא \u0003מעיקרא עינבי השתא חמרא\u0004 \u0005[מתחילה\u0006 היו \u0005ענבים, עכשיו\u0006 הם \u0005יין],\u0006 ובשינוי גדול כזה אפילו הגזלן קונה את גוף הדבר שגזל, וכל שכן האחים, ומדוע יטול הבכור פי שנים במה שהשביחו?","ומשיבים: אין כוונת רב יוסף לומר שהבכור נוטל פי שנים אף בשבח שהושבחו הענבים כשנעשה מהם יין, אלא \u0003כ\u0004מו ש\u0003אמר רב עוקבא בר חמא\u0004 במקום אחר: \u0003ליתן לו דמי היזק ענביו,\u0004 \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 הכוונה היא ש\u0003נותן לו דמי היזק ענביו,\u0004 שאם נתקלקל היין וערכו פחות מערך הענבים — צריכים האחים לשלם לבכור שמחה בהם עבור ירידת ערכם של הענבים שהיו נופלים בחלקו כבכור.","ומעירים: \u0003היכא איתמר\u0004 \u0005[היכן נאמר]\u0006 דבר זה של \u0003רב עוקבא בר חמא? אהא\u0004 \u0005[על זו]\u0006 ש\u0003אמר רב יהודה אמר שמואל: בכור ופשוט שהניח להן אביהן ענבים ובצרום, זיתים ומסקום\u0004 — \u0003בכור נוטל\u0004 מהם \u0003פי שנים אפילו דרכום.\u0004 ותוהים: \u0003דרכום?!\u0004 הלא השתנו הדברים, שכן \u0003מעיקרא עינבי השתא חמרא\u0004 \u0005[מתחילה\u0006 היו \u0005ענבים, עכשיו\u0006 הם \u0005יין]!\u0006 \u0003אמר מר עוקבא בר חמא:\u0004 הכוונה איננה שנותנים לו חלק כפול ביין, אלא \u0003ליתן לו דמי היזק ענביו\u0004 אם נתקלקל היין, שנותנים לו חלק כפול מדמי ענבים.","ועוד \u0003אמר רב אסי\u0004 בענין זה: \u0003בכור שנטל חלק כפשוט\u0004 — \u0003ויתר,\u0004 מחל בכך על חלק הבכורה הראוי לו. ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 עניינו של \u0003\"ויתר\"\u0004 זה? \u0003רב פפא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא אמר: ויתר באותה שדה,\u0004 כלומר, רק לגבי אותו שדה שנחלק ולא נטל בו חלק בכורה הרי זה ויתור, ואין בדבר ויתור על חלק הבכורה בשאר נכסי הירושה. ו\u0003רב פפי\u0004 אף הוא \u0003משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא אמר: ויתר בכל הנכסים כולן.\u0004","ומסבירים: \u0003רב פפא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא אמר ויתר\u0004 רק \u0003באותה שדה, קא סבר\u0004 \u0005[\u0006לפי ש\u0005סבור הוא]:\u0006 \u0003אין לו לבכור\u0004 זכות קניינית בחלק הבכורה \u0003קודם חלוקה,\u0004 ומשום כך רק \u0003מה דאתא לידיה אחיל\u0004 \u0005[שהגיע\u0006 כבר \u0005לידו,\u0006 שחילקו אותו \u0005מחל],\u0006 \u0003אידך\u0004 \u0005[\u0006את \u0005השאר]\u0006 \u0003לא אחיל\u0004 \u0005[מחל].\u0006","\u0003ורב פפי משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא אמר: ויתר בכל הנכסים כולן, קא סבר\u0004 \u0005[\u0006לפי ש\u0005סבור הוא]\u0006 ש\u0003יש לו לבכור\u0004 זכות בחלק הבכורה אף \u0003קודם חלוקה, ומדאחיל בהא אחיל בכולהו\u0004 \u0005[ומכיון שמחל בזו\u0006 השדה \u0005מחל ב\u0006כל הנכסים \u0005כולם].\u0006","ומעירים: \u0003והא\u0004 \u0005[ו\u0006דבר \u0005זה]\u0006 שאמרו \u0003רב פפי ורב פפא\u0004 שניהם בשם רבא — \u0003לאו\u0004 \u0005[לא]\u0006 \u0003בפירוש איתמר\u0004 \u0005[נאמר]\u0006 על ידי רבא, \u0003אלא מכללא\u0004 \u0005[מכלל\u0006 הדברים\u0005]\u0006 \u0003איתמר\u0004 \u0005[נאמר],\u0006 שהיסקנו זאת ממעשה שהיה, \u0003דההוא בכור דאזיל זבין נכסי דידיה\u0004 \u0005[שבכור אחד הלך\u0006 ו\u0005מכר\u0006 קודם חלוקה את \u0005נכסיו שלו]\u0006 ושל אחיו ה\u0003פשוט\u0004 שמת, \u0003אזול יתמי בני\u0004 \u0005[הלכו היתומים בני]\u0006 ה\u0003פשוט למיכל תמרי מהנהו לקוחות\u0004 \u0005[לאכול\u0006 את \u0005התמרים מאותם קונים]\u0006 בגלל החלק של אביהם באותם שדות, \u0003מחונהו\u0004 \u0005[הכו אותם]\u0006 הלקוחות, כאילו היו גנבים. \u0003אמרי להו\u0004 \u0005[אמרו להם]\u0006 ה\u0003קרובים\u0004 לאותם לקוחות: \u0003לא מיסתייא דזבנתינהו לנכסייהו\u0004 \u0005[דייכם שקניתם את נכסיהם]\u0006 שלא כדין, \u0003אלא מימחא נמי מחיתו להו\u0004 \u0005[שגם הכיתם אותם]?\u0006 \u0003אתו לקמיה\u0004 \u0005[באו לפני]\u0006 \u0003רבא, אמר להו\u0004 \u0005[להם]:\u0006 \u0003לא עשה\u0004 הבכור \u0003ולא כלום\u0004 ומכירתו בטלה."],["ובהבנת משמעות דברי רבא נחלקו, \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 רב פפי, \u0005סבור]:\u0006 \u0003לא עשה כלום בפלגא\u0004 \u0005[בחלק]\u0006 של הפשוט, כיון שלא היתה לו רשות למוכרו, אבל את חלק הבכורה מכר, לפי שיש לו בו זכות גם קודם חלוקה. \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 רב פפא, \u0005סבור]:\u0006 \u0003בכולהו\u0004 \u0005[בכולם]\u0006 לא עשה כלום, שאף בחלק הבכורה שלו אין לו חלק.","ובענין זה \u0003שלחו מתם\u0004 \u0005[משם,\u0006 מארץ ישראל לבבל\u0005],\u0006 פסק הלכה: \u0003בכור שמכר קודם חלוקה\u0004 — \u0003לא עשה כלום.\u0004 ומסיקים מכאן: \u0003אלמא\u0004 \u0005[מכאן\u0006 יוצא\u0005]\u0006 לדעת חכמי ארץ ישראל כי \u0003אין לו לבכור קודם חלוקה. ו\u0004מכל מקום \u0003הלכתא\u0004 \u0005[הלכה\u0006 היא\u0005]\u0006 ש\u0003יש לבכור קודם חלוקה.\u0004","וכך גם מסופר ש\u0003מר זוטרא מ\u0004המקום \u0003רישבא פלג בצנא דפלפלי בהדי אחין\u0004 \u0005[חלק בסל של פלפלים יחד עם אחיו]\u0006 \u0003בשוה\u0004 למרות שהיה בכור. \u0003אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003רב אשי\u0004 לדון על השאר, \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הואיל\u0004 ו\u0003ויתרתה במקצת\u0004 — \u0003ויתרתה בכל הנכסים כולן,\u0004 שכן יש לבכור זכות בחלק בכורתו קודם חלוקה.","\u0003האומר: \"איש פלוני\u0004 שהוא \u0003בני בכור לא יטול פי שנים\u0004 בנכסיי \u0003\",\u0004 או אם אמר: \u0003\"איש פלוני בני לא יירש עם\u0004 שאר \u0003אחיו\u0004 בנכסיי \u0003\"\u0004— \u0003לא אמר כלום,\u0004 ומדוע? — מפני \u0003שהתנה על מה שכתוב בתורה,\u0004 וחוק התורה מבטל את דבריו.","אבל \u0003המחלק נכסיו\u0004 בחייו \u0003על\u0004 ידי דיבור \u0003פיו\u0004 כנותן מתנה, הרי אם \u0003ריבה לאחד\u0004 מבניו יותר מחלקם של האחרים \u0003ומיעט לאחד,\u0004 או \u0003השוה להן\u0004 לפשוטים \u0003את הבכור\u0004 — \u0003דבריו קיימין, ואם אמר\u0004 שהוא עושה זאת \u0003משום ירושה\u0004 ולא כמתנה — \u0003לא אמר כלום. כתב\u0004 בתוך שטר הצוואה \u0003בין בתחלה בין באמצע בין בסוף\u0004 שעושה זאת \u0003משום מתנה\u0004 — \u0003דבריו קיימין.\u0004","ושואלים: \u0003לימא מתניתין\u0004 \u0005[האם לומר\u0006 ש\u0005משנתנו]\u0006 ש\u0003לא\u0004 כשיטת \u0003ר' יהודה? דאי\u0004 \u0005[שאם]\u0006 היא כשיטת \u0003ר' יהודה, האמר\u0004 \u0005[הרי\u0006 הוא \u0005אמר]\u0006 במקום אחר כי \u0003בדבר של ממון תנאו קיים!\u0004","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003האומר לאשה: הרי את מקודשת לי על מנת שאין ליך\u0004 (לך) \u0003עלי,\u0004 שאיני מחוייב כלפייך, \u0003שאר\u0004 (מזונות) \u0003כסות ועונה\u0004 (יחסי אישות) שהם חיובי התורה של בעל לאשתו — \u0003הרי זו מקודשת\u0004 כפי שאמר, \u0003ו\u0004אילו \u0003תנאו בטל,\u0004 משום שהתנה על דבר הכתוב בתורה, אלו \u0003דברי\u0004 \u0003ר' מאיר.\u0004 \u0003ר' יהודה אמר:\u0004 המתנה על מה שכתוב בתורה \u0003בדבר של ממון\u0004 — \u0003תנאו קיים,\u0004 כגון חובת הבעל לאשתו בשאר וכסות. ואם כן, לדעת ר' יהודה יכול אדם להתנות שלא יירש בכורו פי שנים, או שאחד מבניו לא יירש כלל!","ודוחים: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שמשנתנו היא כשיטת \u0003ר' יהודה,\u0004 יש לחלק: \u0003התם ידעה וקא מחלה\u0004 \u0005[שם יודעת\u0006 האשה \u0005והיא מוחלת]\u0006 על דבר שמגיע לה, ובזה התנאי קיים, אבל \u0003הכא לא קא מחיל\u0004 \u0005[כאן\u0006 הבן \u0005אינו מוחל]\u0006 על חלקו בירושה, ואין האב יכול להתנות על דבר הכתוב בתורה רק מדעת עצמו.","\u0003אמר רב יוסף: אמר \"איש פלוני בני בכורי הוא\"\u0004 — \u0003נוטל\u0004 אותו אדם \u0003פי שנים\u0004 על סמך דברים אלה, אבל אם אמר כך: \u0003\"איש פלוני\u0004 בני \u0003בכור הוא\"\u0004 — \u0003אינו נוטל פי שנים, דלמא בוכרא דאמא קאמר\u0004 \u0005[שמא בכור של האם אמר]\u0006 ולא בכורו שלו, ואין זה מוכיח שהוא צריך ליטול פי שנים.","מסופר: \u0003ההוא דאתא לקמיה\u0004 \u0005[אדם אחד שבא לפני]\u0006 \u0003רבה בר בר חנה\u0004 להעיד, ו\u0003אמר ליה\u0004 \u0005[לו,\u0006 לרבה בר בר חנה\u0005]:\u0006 \u0003מוחזקני בזה שהוא בכור. אמר ליה\u0004 \u0005[לו]\u0006 רבה בר בר חנה: \u0003מנא ידעת\u0004 \u0005[מנין אתה יודע]\u0006 שהוא בכור? אמר לו: \u0003דהוה קרי ליה אבוה \"בוכרא סכלא\"\u0004 \u0005[שהיה קורא לו אביו \"בכור שוטה\"].\u0006 השיב לו: \u0003דלמא בוכרא דאמא\u0004 \u0005[שמא בכור של האם]\u0006 \u0003הוא,\u0004 ש\u0003כל בוכרא דאמא נמי \"בוכרא סכלא\" קארו ליה\u0004 \u0005[בכור של האם גם כן \"בכור שוטה\" קוראים לו].\u0006","ועוד מסופר: \u0003ההוא דאתא לקמיה\u0004 \u0005[אדם אחד שבא לפני]\u0006 \u0003ר' חנינא\u0004 להעיד. \u0003אמר ליה\u0004 \u0005[לו]\u0006 אותו אדם לר' חנינא: \u0003מוחזקני בזה שהוא בכור. אמר ליה\u0004 \u0005[לו]\u0006 ר' חנינא: \u0003מנא ידעת\u0004 \u0005[מנין אתה יודע]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003דכי הוו אתו לגבי אבוה\u0004 \u0005[שכאשר היו\u0006 אנשים \u0005באים אצל אביו],\u0006 \u0003אמר להו\u0004 \u0005[היה אומר להם]:\u0006 \u0003זילו לגבי\u0004 \u0005[לכו אצל]\u0006 \u0003שכחת ברי\u0004 \u0005[בני],\u0006 \u0003דבוכרא\u0004 \u0003הוא ומסי רוקיה\u0004 \u0005[שבכור הוא ורוקו מרפא].\u0006","ושואלים: \u0003ודלמא בוכרא דאמא\u0004 \u0005[ושמא בכור של האם]\u0006 \u0003הוא!\u0004 ומשיבים: \u0003גמירי\u0004 \u0005[למודים\u0006 אנו\u0005]\u0006 במסורת: \u0003בוכרא דאבא\u0004 \u0005[בכור של האב]\u0006 — \u0003מסי רוקיה\u0004 \u0005[מרפא רוקו],\u0006 \u0003בוכרא דאמא\u0004 \u0005[בכור של האם]\u0006 — \u0003לא מסי רוקיה\u0004 \u0005[מרפא רוקו].\u0006","ועוד בדיני בכור, \u0003אמר\u0004 \u0003ר' אמי: טומטום,\u0004 מי שאיברי הרבייה שלו מכוסים, ולא ידוע אם הוא זכר או נקבה, \u0003שנקרע\u0004 לאחר מכן הכיסוי \u0003ונמצא\u0004 שהוא \u0003זכר,\u0004 אף על פי שהיה בכור — \u0003אינו נוטל פי שנים\u0004 בירושת אביו, שכן \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בפרשת בכור: \u0003\"והיה הבן הבכר לשניאה\"\u0004 (דברים כא, טו), והכוונה היא: \u0003עד שיהא בן משעת הויה,\u0004 כלומר, משעה שנהיה, שנולד, וזה לא היה בן בתחילתו אלא טומטום.","\u0003רב נחמן בר יצחק אמר:\u0004 טומטום שנקרע ונמצא זכר \u0003אף אינו נידון כבן סורר ומורה,\u0004 שכן \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"כי יהיה לאיש בן סורר ומרה\"\u0004 (דברים כא, יח), והכוונה אף כאן: \u0003עד שיהא בן משעת הויה.\u0004"],["\u0003אמימר אמר:\u0004 טומטום זה שנקרע ונמצא זכר, אם הוא בן פשוט ולא בן בכור, \u0003אף אינו ממעט חלק בכורה,\u0004 שאין מביאים אותו בחשבון הבנים החולקים בירושה כאשר נותנים לבכור פי שנים מכל אחד מן האחים. שאם היו שלושה אחים — בכור, פשוט וטומטום, חולקים את הרכוש לשלושה חלקים וכאילו חולקים רק הבכור והפשוט, ונוטל הבכור לחלק בכורתו שליש ואת אותם שני שליש הנותרים יחלקו ביניהם בשווה הבכור הפשוט והטומטום. \u0003שנאמר\u0004 בפרשת הבכור: \u0003\"וילדה לו בנים\u0004 והיה הבן הבכור \u0003\"\u0004וכו' (דברים כא, טו), \u0003עד שיהא בן בשעת לידה\u0004 שבדין הבכור אין נחשב בין הבנים אלא מי שהיה בן משעת לידתו.","\u0003רב שיזבי אמר: אף אינו נימול לשמנה\u0004 ימים, אם חל היום השמיני ללידתו בשבת, למרות שבדרך כלל מילה ביום השמיני דוחה את השבת, ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"אשה כי תזריע וילדה זכר... וביום השמיני ימול\"\u0004 (ויקרא יב, ב–ג), לומר שאינו נימול ביום השמיני (ואף בשבת) \u0003עד שיהא זכר משעת לידה\u0004 (\"וילדה זכר\").","\u0003רב שרביא אמר: אף אין אמו טמאה לידה\u0004 כטומאת כל אשה היולדת בן, ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"אשה כי תזריע וילדה זכר וטמאה שבעת ימים\",\u0004 וכוונתו \u0003עד שיהא זכר משעת לידה.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים\u0006 על כך\u0005]\u0006 ממה ששנינו: אשה \u0003המפלת טומטום ואנדרוגינוס\u0004 — \u0003תשב\u0004 ימי טומאה. ומכיון שהוא ספק אם זכר או נקיבה, הריהי טמאה גם \u0003ל\u0004פי ההנחה שהיה זה \u0003זכר ו\u0004גם \u0003ל\u0004פי ההנחה שהיא \u0003נקבה.\u0004 ואם כן הרי זו \u0003תיובתיה\u0004 \u0005[קושיה חמורה עליו]\u0006 על \u0003רב שרביא,\u0004 שסבור שהיולדת טומטום אינה טמאה כלל טומאת לידה! ומסכמים: אכן זו היא \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 שאין עליה תשובה, ונדחו דבריו.","ואומרים: \u0003לימא תיהוי תיובתא\u0004 \u0005[שמא נאמר\u0006 ש\u0005תהא\u0006 זו \u0005קושיה חמורה]\u0006 גם על \u0003רב שיזבי\u0004 לענין מילה, שהרי גם הוא דורש \"וילדה זכר\" — רק אם בשעת לידה ידוע בוודאי שזכר הוא!","ומשיבים: ה\u0003תנא\u0004 שאמר לגבי טומאת יולדת, לא בוודאות אמר שהיא טמאה טומאת לידה, אלא \u0003ספוקי מספקא ליה ולחומרא\u0004 \u0005[מסופק לו\u0006 הדבר, \u0005ו\u0006הוא פוסק \u0005להחמיר],\u0006 לדון אשה זאת כיולדת זכר או נקיבה. ומספק זה עצמו יש לומר שפסק כרבי שיזבי שאין למולו בשבת, שמא אין זה בכלל \"וילדה זכר\".","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שרק מפני הספק הוא, \u0003תשב\u0004 בין \u0003לזכר ו\u0004בין \u0003לנקבה ו\u0004בין \u0003לנדה מיבעי ליה\u0004 \u0005[נצרך לו\u0006 לומר\u0005],\u0006 שמא אין זו נחשבת לידה, ומספק נחיל גם דיני נדה על הדם שאשה זו רואה בכל התקופה שאחר הלידה! ומסכמים: אכן, \u0003קשיא\u0004 \u0005[קשה\u0006 הדבר\u0005].\u0006","\u0003אמר רבא, תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003ר' אמי\u0004 שטומטום שנקרע ונמצא זכר אינו נוטל חלק בכורה אם נולד ראשון: נאמר בדין הבכור \"והיה הבן הבכור\" (דברים כא, טו), ויש לדייק: \u0003\"בן\"\u0004 — \u0003ולא טומטום, \"בכור\"\u0004 — \u0003ולא ספק.\u0004","ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 הלימוד \u0003\"בן\" ולא טומטום\u0004 הרי זה בא ללמדנו \u0003כ\u0004מו שאמר \u0003ר' אמי,\u0004 שאין הטומטום נידון כבכור. \u0003אלא \"בכור\" ולא ספק, לאפוקי מאי\u0004 \u0005[להוציא\u0006 למעט את \u0005מה]\u0006 הוא בא?","ומשיבים: \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003מ\u0004מה ש\u0003דרש רבא,\u0004 ש\u0003דרש רבא\u0004 ברבים הלכה זו: \u0003שתי נשים\u0004 של אדם אחד \u0003שילדו שני\u0004 בנים \u0003זכרים במחבא,\u0004 במקום בו לא נראו על ידי אחרים, ולא ידוע מי מהם נולד ראשון והוא בכור לאביו, ואחרי כן נולדו לאביהם בנים נוספים — \u0003כותבין\u0004 שני הבנים הללו \u0003הרשאה זה לזה,\u0004 וכשידחו האחים האחרים כל אחד מהם מלתת לו פי שנים בטענה שאין הוא בכור, יוכל כל אחד מהם לגבות את חלק הבכור, בין עבור עצמו ובין עבור האח השני.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לרבא\u0004 אחרי שדרש כך: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003שלח רבין\u0004 מארץ ישראל לבבל, איגרת זו: \u0003דבר זה שאלתי לכל רבותי ולא אמרו לי דבר, ברם\u0004 (אבל) \u0003כך אמרו משום\u0004 (בשם) \u0003ר' ינאי:\u0004 אם \u0003הוכרו,\u0004 שמתחילה היה ידוע מי מבין השניים הללו הוא הבכור, \u0003ולבסוף נתערבו\u0004 ושוב אין יודעים מי הוא הבכור — \u0003כותבין הרשאה זה לזה.\u0004 אבל אם \u0003לא הוכרו\u0004 גם מתחילה — \u0003אין כותבין הרשאה זה לזה!\u0004","\u0003הדר אוקי\u0004 \u0005[חזר\u0006 ו\u0005העמיד]\u0006 \u0003רבא אמורא עליה\u0004 \u0005[מתורגמן עליו]\u0006 שישמיע את דבריו בקול רם ויסבירם, \u0003ודרש: דברים שאמרתי לכם\u0004 מקודם \u0003טעות הן בידי, ברם כך אמרו משום\u0004 \u0003ר' ינאי: הוכרו ולבסוף נתערבו\u0004 — \u0003כותבין הרשאה זה לזה, לא הוכרו\u0004 כלל — \u0003אין כותבין הרשאה זה לזה,\u0004 והוא שאמרו: \"בכור\" ולא ספק, שאם מתחילה היה ספק — אינו נחשב כבכור.","\u0003שלחו ליה\u0004 \u0005[לו]\u0006 \u0003בני\u0004 המקום \u0003אקרא דאגמא לשמואל, ילמדנו רבינו\u0004 תשובה לשאלה זו: \u0003היו מוחזקין בזה,\u0004 באחד האחים, \u0003שהוא בכור, ואמר אביו על אחר \"בכור הוא\", מהו\u0004 הדין בכגון זה, האם סומכים על החזקה או על דברי האב? \u0003שלח להו\u0004 \u0005[להם]\u0006 שמואל בתשובה: שני האחים הללו, זה המוחזק כבכור, וזה שאמר עליו האב שהוא בכור, \u0003כותבין הרשאה\u0004"],["\u0003זה לזה.\u0004","ושואלים על פסיקתו זו של שמואל: \u0003מה נפשך\u0004 \u0005[מה רצונך]?\u0006 מהי דעתו של שמואל? \u0003אי כרבנן סבירא ליה\u0004 \u0005[אם כ\u0006דעת \u0005חכמים סבור הוא\u0006 שמואל\u0005]\u0006 בענין זה, \u0003לישלח להו\u0004 \u0005[שישלח להם]\u0006 תשובה \u0003כ\u0004דברי \u0003רבנן\u0004 \u0005[חכמים],\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003כ\u0004דעת \u0003ר' יהודה סבירא ליה\u0004 \u0005[סבור הוא],\u0006 \u0003לישלח להו\u0004 \u0005[שישלח להם]\u0006 תשובה \u0003כ\u0004דעת \u0003ר' יהודה,\u0004 ואילו תשובתו אינה כדעת אחד מהם!","ומשיבים: \u0003מספקא ליה אי\u0004 \u0005[מסופק לו אם]\u0006 הלכה \u0003כ\u0004שיטת \u0003ר' יהודה אי כרבנן\u0004 \u0005[אם כ\u0006שיטת \u0005חכמים],\u0006 ומפני הספק אמר שיעשו בדרך שיצאו ידי כולם.","ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 \u0003היא\u0004 אותה מחלוקת שבין ר' יהודה וחכמים? ומשיבים, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 מה שנאמר \"כי את הבכור בן השנואה \u0003יכיר\u0004 לתת לו פי שנים\" (דברים כא, יז) כוונתו — \u0003יכירנו לאחרים,\u0004 שהאב קובע ומודיע שזה שהוא בכור.","\u0003מכאן אמר\u0004 \u0003ר' יהודה: נאמן אדם לומר\u0004 על אחד מבניו (ואף על אדם אחר) \u0003\"זה בני בכור\",\u0004 גם כאשר היו לו בנים גדולים יותר, או שהיה בן אחד מוחזק כבכור. \u0003וכשם שנאמן אדם לומר \"זה בני בכור\", כך נאמן אדם\u0004 שהוא כהן \u0003לומר \"\u0004בני \u0003זה\u0004 הוא \u0003בן\u0004 שנולד לי מ\u0003גרושה\", ו\u0004כן \u0003\"\u0004בני \u0003זה\u0004 הוא \u0003בן חלוצה\"\u0004 (שעשתה חליצה ליבמה) שאינו כשר לכהונה, אלא חלל הוא. \u0003וחכמים אומרים: אינו נאמן\u0004 האב, לא לגבי הבכור ולא לגבי בן הגרושה ובן החלוצה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב נחמן בר יצחק לרבא: בשלמא\u0004 \u0005[נניח]\u0006 \u0003לר' יהודה\u0004 — \u0003היינו דכתיב\u0004 \u0005[זהו שנאמר]\u0006 \u0003\"יכיר\",\u0004 שהכתוב מודיענו שיש לאב נאמנות בענין בניו. \u0003אלא לרבנן\u0004 \u0005[ל\u0006דעת \u0005חכמים]\u0006 \u0003\"יכיר\" למה לי,\u0004 ומה כתוב זה מלמדנו?","ומשיבים: הכתוב מדבר \u0003ב\u0004מי ש\u0003צריך היכרא\u0004 \u0005[היכר],\u0006 כשלא היה הדבר ידוע מי מבין הבנים הוא הבן הבכור. אבל במקום שמוחזק אחד הבנים כבן הבכור — אין האב יכול לומר על בן אחר שהוא הבכור.","וחוזרים ומקשים על דברי חכמים: לשיטתם \u0003למאי הלכתא\u0004 \u0005[למה,\u0006 לאיזו \u0005הלכה]\u0006 אמרו שהאב יכול להכיר בבנו כבכור? — אם תאמר שאמרו כן לענין \u0003למיתבא\u0004 \u0005[לתת]\u0006 \u0003לו פי שנים,\u0004 בירושה, ואולם דבר זה אינו צריך לכתוב מיוחד, שהרי \u0003לא יהא\u0004 זה \u0003אלא\u0004 אדם \u0003אחר\u0004 זר, \u0003אילו בעי למיתבא ליה\u0004 \u0005[היה רוצה\u0006 האב \u0005לתת לו]\u0006 פי שנים מבניו \u0003במתנה, מי\u0004 \u0005[האם]\u0006 \u0003לא יהיב ליה\u0004 \u0005[\u0006היה יכול \u0005לתת לו]?\u0006 ואם כן אין צורך כלל ללמוד דבר זה מ\"יכיר\"!","ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 הלכה זו אלא \u0003בנכסים שנפלו לו\u0004 לאב \u0003לאחר מכאן,\u0004 לאחר שאמר עליו האב שהוא בכור. שאם היה הדבר משום מתנה — לא יכול היה הבן לקנות אותם, משום שהם דבר שעדיין לא הגיע לידי האב ואין אדם מקנה דבר שלא בא לעולם. אבל אם הוא מטעם \"יכיר\", שסומכים על דברי האב שבן זה הוא בכור — הריהו יורש כבכור בכל מה שיפול לידי אביו עד מותו.","ושואלים: \u0003ול\u0004דעת \u0003ר' מאיר\u0004 ש\u0003אמר: אדם מקנה דבר שלא בא לעולם,\u0004 וניתן היה איפוא להקנות נכסים אלו לכל אדם, אם כן \u0003\"יכיר\"\u0004 בבכור \u0003למה לי?\u0004","ומשיבים: ללמד שהוא זוכה על ידי הכרת האב גם \u0003בנכסים שנפלו\u0004 (שיפלו) \u0003לו\u0004 לאב \u0003כשהוא גוסס\u0004 כאשר אינו יכול לתת מתנה. ונכסים כאלו, גם לדעת ר' מאיר לא יכול אדם להקנות מראש, אבל מכח הכרת האב בבן כבכור — הריהו יורש גם נכסים אלו.","ועוד בענין זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בברייתא\u0005]:\u0006 \u0003היו מוחזקין בו\u0004 באדם מסויים \u0003שהוא בכור, ואמר אביו על\u0004 בן \u0003אחר\u0004 שלו \u0003שהוא בכור\u0004 — הרי האב \u0003נאמן. היו מוחזקין בו שאינו בכור, ואמר אביו\u0004 ש\u0003בכור הוא\u0004 — \u0003אינו נאמן.\u0004","ומעירים: שתי הלכות מנוגדות אלו שנשנו בברייתא יש לפרשן כך: \u0003רישא\u0004 \u0005[ראשה]\u0006 של הברייתא היא כדעת \u0003ר' יהודה, וסיפא רבנן\u0004 \u0005[וסופה\u0006 כדעת \u0005חכמים].\u0006","\u0003אמר\u0004 \u0003ר' יוחנן: אמר\u0004 על אדם מסויים \u0003\"בני הוא\", וחזר ואמר \"עבדי הוא\"\u0004 — \u0003אינו נאמן\u0004 לומר עליו שהוא עבד, לפוסלו ולהוציאו מכלל יורשיו. אבל אם אמר על אדם מסויים \u0003\"עבדי הוא\", וחזר ואמר \"בני הוא\"\u0004 — \u0003נאמן,\u0004 שיש להבין כי מה שאמר בתחילה \"עבדי הוא\" — ש\u0003משמש לי כעבדא\u0004 \u0005[כעבד]\u0006 \u0003קאמר\u0004 \u0005[אמר].\u0006","ומעירים: \u0003וחילופיה\u0004 \u0005[וחילופו]\u0006 של דבר נאמר על \u0003בית המכס:\u0004 \u0003היה עובר על בית המכס ואמר\u0004 על אדם מסויים \u0003\"בני הוא\", וחזר ואמר\u0004 לאחר מכן \u0003\"עבדי הוא\"\u0004 — הרי זה \u0003נאמן\u0004 בדבריו האחרונים שהוא עבד, שיש להבין שאמר עליו \"בני\" רק כדי להתחמק מתשלום המכס שהיו מטילים על העבדים. אבל אם \u0003אמר\u0004 עליו בהיותם בבית המכס \u0003\"עבדי הוא\", וחזר ואמר\u0004 לאחר מכן \u0003\"בני הוא\"\u0004 — \u0003אינו נאמן\u0004 שהוא בנו, שאין אדם מחייב עצמו סתם במכס וקורא לבנו \"עבדי\".","\u0003מיתיבי\u0004 \u0005[מקשים\u0006 על כך\u0005]\u0006 ממה ששנינו בברייתא: \u0003היה\u0004 אדם \u0003משמשו כבן\u0004 המשמש את אביו, \u0003ובא\u0004 האב \u0003ואמר \"בני הוא\", וחזר ואמר\u0004 אחר כך \u0003\"עבדי הוא\"\u0004 — \u0003אינו נאמן.\u0004 וכן להיפך, אם \u0003היה משמשו כעבד\u0004 את רבו, שהיה נוהג בו כדרך שנוהג עבד באדוניו, \u0003ובא ואמר \"עבדי הוא\", וחזר ואמר\u0004 אחר כך \u0003\"בני הוא\"\u0004 — \u0003אינו נאמן.\u0004 ואילו ר' יוחנן אמר שאם אמר בתחילה \"עבדי הוא\" וחזר ואמר \"בני הוא\" — נאמן!","\u0003אמר רב נחמן בר יצחק: התם\u0004 \u0005[שם]\u0006 שאינו נאמן להחשיבו לאחר מכן כבן, הרי זה במקרה \u0003דקארו ליה\u0004 \u0005[שקראו לו]:\u0006 \u0003\"עבדא מצר\u0004 \u0005[עבד\u0006 ש\u0005גבולו]\u0006 \u0003מאה\".\u0004 שכיון שכולם קראוהו \"עבד\", ולא רק הוא אמר שעבד הוא — אינו יכול להוציאו מגדר עבד. ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"מצר מאה\"?\u0004 ומשיבים: הכוונה היא \u0003מצר עבדא מאה זוזי\u0004 \u0005[\u0006ש\u0005גבולו\u0006 של ה\u0005עבד,\u0006 שוויו, \u0005מאה זוז].\u0006","\u0003שלח ליה\u0004 \u0005[לו]\u0006 \u0003ר' אבא\u0004 מארץ ישראל \u0003לרב יוסף בר חמא\u0004 כמה הלכות; \u0003האומר לחבירו: \"עבדי גנבת\", והוא אומר: \"לא גנבתי\".\u0004 טוען האיש: \u0003\"\u0004אם כן, \u0003מה טיבו אצלך\",\u0004 כלומר, מה הוא עושה אצלך? ואומר לו הנטען: \u0003\"אתה מכרתו לי\",\u0004"],["או שטוען: \u0003\"אתה נתתו לי במתנה\",\u0004 ומוסיף ואומר: \"העבד הוא בוודאי שלי ואיני חייב לך דבר, ומכל מקום אם \u0003רצונך\u0004 בכך \u0003השבע\u0004 ששלך הוא \u0003וטול\u0004 אותו\". \u0003ונשבע\u0004 התובע שהוא שלו — \u0003אינו יכול\u0004 הנתבע \u0003לחזור בו\u0004 מהצעתו זו שהתובע ישבע ויטול, אף שמן הדין לא היה צריך לקבל על עצמו דבר זה כלל.","ושואלים: \u0003מאי קא משמע לן\u0004 \u0005[מה השמיע לנו\u0006 בכך\u0005]\u0006 ר' אבא? הלא כבר \u0003תנינא\u0004 \u0005[שנינו\u0006 במשנה\u0005]\u0006 שאם \u0003אמר לו\u0004 למי שבא עמו בדין: \u0003\"נאמן עלי אבא\u0004 (אבי), לשמש כדיין בדין שבינינו \u0003\",\u0004 אף שמן הדין פסול הוא לשמש כדיין, או: \u0003\"נאמן עלי אביך\",\u0004 או \u0003\"נאמנין עלי שלשה רועי בקר\"\u0004 (שהם אנשים שאינם בקיאים בדין) למרות שכל אלו פסולים לדון, \u0003ר' מאיר אומר:\u0004 אף שאמר כן — \u0003יכול לחזור בו, וחכמים אומרים: אינו יכול לחזור בו\u0004 ועליו לקבל כל דין שיפסקו. ואם כן מה חידש ר' אבא?","ומשיבים: בפירוש משנה זו דנו אם מחלוקת ר' מאיר וחכמים היא דווקא במי שמוכן לוותר על תביעתו על פי דיינים אלה (\"מחול לך\"), או אף ב\"אתן לך\" נחלקו, כשקיבל על עצמו לשלם לפי דינים אלה, שאף בזה סבורים חכמים שאינו יכול לחזור בו, ולא הובהרה מחלוקתם זו. ור' אבא \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה השמיע לנו],\u0006 שאף \u0003ב\"אתן לך\" מחלוקת, ו\u0004ש\u0003הלכה\u0004 במחלוקת זו \u0003כדברי חכמים.\u0004","ועוד \u0003שלח ליה\u0004 \u0005[לו]\u0006 \u0003ר' אבא לרב יוסף בר חמא, הלכה: גובין\u0004 חובות של האב \u0003מן העבדים\u0004 שהוריש האב ליתומים, משום שדין עבדים כדין מקרקעין. \u0003ורב נחמן אמר: אין גובין.\u0004","ועוד \u0003שלח ליה\u0004 \u0005[לו]\u0006 \u0003ר' אבא לרב יוסף בר חמא,\u0004 \u0003הלכה\u0004 בענייני עדות בבית דין: מי שקרוב לאדם אחר קירבת משפחה של \u0003שלישי בשני,\u0004 כגון נכדו של אח אחד המעיד עבור בן האח השני — הרי הוא \u0003כשר\u0004 לעדות זו, שאין הוא נחשב קרוב הפסול לעדות. \u0003רבא אמר:\u0004 שלישי כשר \u0003אף בראשון,\u0004 כלומר, להעיד לאחי סבו.","ומוסיפים, \u0003מר בר רב אשי אכשר באבא דאבא\u0004 \u0005[הכשיר באבי האב],\u0006 כלומר, הכשיר עדות של נכד לסבו, שהחשיב אותו כשלישי בראשון שהכשיר רבא. ומעירים: \u0003ולית הלכתא\u0004 \u0005[ואין הלכה]\u0006 \u0003כמר בר רב אשי\u0004 בענין זה.","ועוד \u0003שלח ליה\u0004 \u0005[לו]\u0006 \u0003ר' אבא לרב יוסף בר חמא\u0004 הלכה בדיני עדות: אדם ש\u0003היה יודע לו\u0004 לחבירו \u0003בעדות קרקע\u0004 מסויימת \u0003עד שלא נסתמא,\u0004 כלומר, קודם שנתעוור, כשהיה אדם פיקח, \u0003ונסתמא\u0004 לאחר מכן — \u0003פסול\u0004 להעיד לו עתה כשהוא עיוור.","\u0003ושמואל אמר: כשר\u0004 הוא, ומדוע? \u0003אפשר דמכוין מצרנהא\u0004 \u0005[יכול לכוון,\u0006 להגדיר במדוייק\u0005,\u0006 היכן \u0005המצרים,\u0006 גבולות השדה\u0005],\u0006 ולכן עדותו עדות. \u0003אבל\u0004 בעדות הנוגעת למיטלטלין כגון \u0003גלימא\u0004 — \u0003לא\u0004 יכול להעיד שהיא שייכת לאדם מסויים, משום שאינו רואה אותה. \u0003ורב ששת אמר: אפילו\u0004 ב\u0003גלימא\u0004 יכול להעיד, \u0003אפשר\u0004 לו ויכול הוא \u0003דמכוין\u0004 \u0005[לכוון]\u0006 לדייק ב\u0003מדת ארכו ומדת רחבו\u0004 של הלבוש, לזכור מה היה גודלה של הגלימה, ולהעיד על כך. \u0003אבל\u0004 בעדות הנוגעת ל\u0003נסכא\u0004 \u0005[חתיכת כסף]\u0006 — \u0003לא. ורב פפא אמר: אפילו\u0004 בענין \u0003נסכא\u0004 \u0005[חתיכת כסף]\u0006 עדותו כשרה, שכן \u0003אפשר מכוין\u0004 \u0005[לכוון]\u0006 בדיוק ב\u0003מדת משקלותיו,\u0004 ויודעים על ידי כך שזו אותה חתיכה.","\u0003מיתיבי\u0004 \u0005[מקשים\u0006 על כך\u0005]\u0006 ממה ששנינו בברייתא: מי ש\u0003היה יודע לו\u0004 לחבירו \u0003בעדות עד שלא נעשה חתנו, ונעשה\u0004 אחר כך \u0003חתנו,\u0004 שנשא את בתו לאשה, והריהו עתה קרוב הפסול להעיד לו. או שראה דבר מה כעד כשהיה \u0003פיקח ונתחרש,\u0004 או היה \u0003פיתח\u0004 (אדם רואה) כשראה אותה עדות, \u0003ו\u0004אחר כך \u0003נסתמא,\u0004 או היה \u0003שפוי ונשתטה\u0004 — הרי זה \u0003פסול\u0004 להעיד.","\u0003אבל\u0004 אם \u0003היה יודע לו בעדות עד שלא נעשה חתנו, ונעשה חתנו, ו\u0004אחר כך \u0003מתה בתו,\u0004 ועתה הם אינם קרובים. או שהיה \u0003פיקח ונתחרש וחזר ונתפקח, פיתח ונסתמא וחזר ונתפתח, שפוי ונשתטה וחזר ונשתפה\u0004 — בכל אלה הריהו \u0003כשר\u0004 לעדות.","\u0003זה הכלל: כל שתחלתו\u0004 כשרואה את המעשה, \u0003או סופו\u0004 כשמעיד על כך, \u0003בפסלות\u0004 — \u0003פסול,\u0004 אבל אם היה \u0003תחלתו וסופו בכשרות\u0004 — \u0003כשר,\u0004 גם אם בינתיים היה פסול."],["הרי זו \u0003תיובתא דכולהו\u0004 \u0005[קושיה חמורה על כולם]\u0006 על שמואל ורב ששת ורב פפא, שהם אומרים שמי שהיה פיתח ואחר כך נסתמא יכול להעיד. ומסכמים: אכן, \u0003תיובתא\u0004 \u0005[קושיה חמורה\u0006 היא\u0005]\u0006 ונדחו דבריהם.","ועוד הלכה \u0003שלח\u0004 \u0003ר' אבא לרב יוסף בר חמא: האומר על תינוק בין הבנים\u0004 — \u0003נאמן. ור' יוחנן אמר: אינו נאמן.\u0004","ושואלים: \u0003מאי קאמר\u0004 \u0005[מה אמר]\u0006 באיזה מקרה דיבר ר' אבא? \u0003אמר אביי, הכי קאמר\u0004 \u0005[כך אמר]:\u0006 אב \u0003האומר על תינוק בין הבנים\u0004 \u0003\"\u0004בן זה \u0003יירש כל נכסי\"\u0004 — \u0003נאמן,\u0004 והרי זה \u0003כ\u0004שיטת \u0003ר' יוחנן בן ברוקה\u0004 שאמר שיכול אדם להנחיל את נכסיו כולם לאחד מאלו הראויים ליורשו. \u0003ור' יוחנן אמר: אינו נאמן,\u0004 שהוא סבור \u0003כרבנן\u0004 \u0005[כחכמים]\u0006 החולקים על ר' יוחנן בן ברוקה.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רבא:\u0004 לפי פירושו של אביי, \u0003האי\u0004 \u0005[זה]\u0006 הביטוי \u0003\"נאמן\" ו\"אינו נאמן\"\u0004 אינו מתאים לפירוש זה, אלא \u0003\"יירש\" ו\"לא יירש\" מבעיא ליה\u0004 \u0005[נצרכה לו\u0006 לומר\u0005],\u0006 שהרי אין מדובר כלל בענין של נאמנות!","\u0003אלא אמר רבא, הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003האומר על תינוק בין הבנים \"בכור הוא\"\u0004 — \u0003נאמן, כ\u0004דברי \u0003ר' יהודה. ור' יוחנן אמר: אינו נאמן, כ\u0004דברי \u0003רבנן\u0004 \u0005[חכמים]\u0006 החולקים עליו.","ועוד הלכה \u0003שלח ליה\u0004 \u0005[לו]\u0006 \u0003ר' אבא לרב יוסף בר חמא: האומר \"תטול אשתי\u0004 בירושה \u0003כאחד מן הבנים\"\u0004 — הרי זו \u0003נוטלת כאחד מן הבנים,\u0004 שהרי רשאי הוא לתת לה מה שירצה כמתנה. \u0003אמר רבא: ו\u0004דברים אלה אמורים רק \u0003בנכסים של עכשיו\u0004 שאותם יכול לתת במתנה, אבל לא במה שיקנה בעתיד, שאינו יכול לתת מה שעדיין לא בא לעולם. \u0003ו\u0004כן מדובר בכל הבנים שיהיו בזמן החלוקה, אף \u0003בבנים הבאין לאחר מכאן,\u0004 שנולדו לו לאחר שנתן לה מתנה זו, כפי מספרם באותו זמן.","ועוד הלכה \u0003שלח ליה\u0004 \u0005[לו]\u0006 \u0003ר' אבא לרב יוסף בר חמא: המוציא שטר חוב על חבירו,\u0004 ה\u0003מלוה אומר: לא נפרעתי,\u0004 לא קיבלתי, \u0003כלום, ולוה אומר: פרעתי מחצה,\u0004 \u0003והעדים\u0004 באים ו\u0003מעידין שפרע\u0004 את החוב \u0003כולו,\u0004 מה עושים במקרה זה? \u0003הרי זה\u0004 הלווה \u0003נשבע\u0004 שאכן שילם מחצה, כדין כל המודה במקצת הטענה, ופטור מלשלמו, \u0003וגובה\u0004 המלוה \u0003מחצה\u0004 מן החוב. ואולם דווקא \u0003מנכסים בני חורין, אבל ממשועבדין\u0004 (נכסים שמכר הלווה לאחרים לאחר ההלוואה) \u0003לא\u0004 גובה, \u0003דאמרי\u0004 \u0005[שאומרים]\u0006 הקונים: \u0003אנן\u0004 \u0005[אנו]\u0006 על ה\u0003עדים סמכינן\u0004 \u0005[סומכים אנו],\u0006 והרי העדים מעידים שהחוב נפרע כולו, ואין המלוה רשאי איפוא לקחת מאיתנו לפרעון חובו. ומשווים את הדבר למחלוקת בענין שטר חוב שהיה כתוב בו שחייב הלווה \"סלעים\" (בלי ציון כמה הם), שהמלוה טוען שהיו חמישה, והלווה מודה בשלושה, ושם נחלקו ר' שמעון בן אלעזר ור' עקיבא האם הלווה חייב להישבע כדין מודה במקצת.","ואומרים: \u0003ואפילו ל\u0004דעת \u0003ר' עקיבא\u0004 ש\u0003אמר\u0004 שאינו צריך להישבע כדין מודה במקצת, לפי ש\u0003משיב אבדה הוי\u0004 \u0005[הוא]\u0006 בסלע השלישי, שהרי בלא הודאתו לא היה יכול המלוה לגבות יותר משני סלעים, כלשון השטר (\"סלעים\"), מכל מקום \u0003הני מילי היכא דליכא\u0004 \u0005[דברים אלה אמורים\u0006 דווקא \u0005במקום שאין]\u0006 \u0003עדים\u0004 שהיה חייב לו כסף, \u0003אבל היכא דאיכא\u0004 \u0005[במקום שיש]\u0006 \u0003עדים\u0004 — יש להניח כי \u0003אירתותי אירתת\u0004 \u0005[מפחד]\u0006 הלווה להכחיש הכל, ולכן הודה במחצה, ומשום כך צריך להישבע, כדין מודה במקצת.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003מר בר רב אשי: אדרבה\u0004 \u0005[גדולה מזו,\u0006 להיפך\u0005],\u0006 \u0003אפילו לר' שמעון בן אלעזר\u0004 ש\u0003אמר\u0004 שם כי \u0003מודה מקצת הטענה הוי\u0004 \u0005[הוא]\u0006 וצריך להישבע, \u0003הני מילי היכא דליכא\u0004 \u0005[דברים אלה\u0006 אמורים דווקא \u0005במקום שאין]\u0006 \u0003עדים דקא מסייעי ליה\u0004 \u0005[שמסייעים לו]\u0006 ללווה, \u0003אבל היכא דאיכא\u0004 \u0005[במקום שיש]\u0006 \u0003עדים דקא מסייעי ליה\u0004 \u0005[שמסייעים לו]\u0006 ואומרים שפרע הכל — \u0003ודאי משיב אבדה הוי\u0004 \u0005[הריהו]\u0006 ואינו צריך להישבע שפרע מחצה.","\u0003דרש מר זוטרא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב שימי בר אשי: הלכתא\u0004 \u0005[ההלכה]\u0006 \u0003בכל הני שמעתתא\u0004 \u0005[השמועות הללו]\u0006 \u0003כ\u0004פי ש\u0003שלח ליה\u0004 \u0005[לו]\u0006 \u0003ר' אבא לרב יוסף בר חמא. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי:\u0004 ואותה הלכה שחלק עליה \u0003רב נחמן\u0004 שגובים מעבדים, \u0003מאי\u0004 \u0005[מה\u0006 דינה\u0005]?\u0006 האם אף בזאת הלכה כר' אבא? והלא ידוע שהלכה כרב נחמן בדינים! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 הלכה זו, בלשון \u0003\"אין גובין\" מתנינן לה\u0004 \u0005[שונים אנו אותה]\u0006 בשם ר' אבא, ואנו מוסיפים: \u0003וכן אמר רב נחמן.\u0004 ואם כן אף בזו הלכה כר' אבא.","ושואלים: אם כן, \u0003ואלא\u0004 מה שדרש מר זוטרא \u0003הלכתא\u0004 \u0005[הלכה\u0006 כר' אבא\u0005]\u0006 \u0003לאפוקי מאי\u0004 \u0005[להוציא,\u0006 למעט, \u0005ממה]?\u0006"],["\u0003אי לאפוקי\u0004 \u0005[אם להוציא,\u0006 למעט, לשלול\u0005]\u0006 \u0003מ\u0004דברי \u0003רבא,\u0004 שמכשיר עדות של שלישי בראשון — הלא אינו חולק על דברי ר' אבא שהכשיר שני בשלישי, אלא \u0003מוסיף הוא\u0004 עליהם! \u0003אי\u0004 \u0005[אם]\u0006 כדברי \u0003מר בר רב אשי\u0004 שהכשיר עדות של סב ונכדו — הרי כבר פסקנו לעיל במפורש כי \u0003לית הלכתא\u0004 \u0005[אין הלכה]\u0006 \u0003כמר בר רב אשי! אי לאפוקי\u0004 \u0005[אם להוציא]\u0006 \u0003מ\u0004דברי \u0003שמואל ורב ששת ורב פפא,\u0004 שמי שנסתמא יכול להעיד על מה שראה קודם לכן — \u0003הא איתותבו\u0004 \u0005[הרי\u0006 כבר \u0005הופרכו]\u0006 מברייתא!","\u0003אלא\u0004 נאמרו הדברים \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003מ\u0004מה שאמר \u0003ר' יוחנן,\u0004 שאינו נאמן להעיד על תינוק בין הבנים שהוא בכור, \u0003ומאתקפתא\u0004 \u0005[ומקושייתו]\u0006 של \u0003מר בר רב אשי\u0004 על דברי ר' אבא, בענין המודה במקצת חוב שבשטר ועדים מעידים שפרעו כולו, שלדעת מר בר רב אשי אינו חייב שבועה.","שנינו במשנה: \u0003המחלק נכסיו על פיו,\u0004 בצוואת שכיב מרע, באופן ש\u0003ריבה לאחד\u0004 מבניו \u0003ומיעט לאחד,\u0004 כל זמן שאמר לשון מתנה בנוסף ללשון ירושה, אם בתחילה או בסוף או באמצע — דבריו קיימים. ומבררים דברים אלה: \u0003היכי דמי\u0004 \u0005[כיצד הוא בדיוק]\u0006 לשון \u0003מתנה בתחלה, היכי דמי\u0004 \u0005[כיצד הוא בדיוק]\u0006 לשון מתנה \u0003באמצע, היכי דמי\u0004 \u0005[כיצד הוא בדיוק]\u0006 \u0003בסוף?\u0004","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל \u0003אמר\u0004 בשם \u0003ר' יוחנן\u0004 בהסבר המשנה: אם אמר \u0003\"תנתן שדה פלונית לפלוני ויירשה\"\u0004 — \u0003זו היא\u0004 לשון \u0003מתנה בתחלה,\u0004 אם אמר \u0003\"ויירשה ותנתן לו\"\u0004 — \u0003זו היא\u0004 לשון \u0003מתנה בסוף, \"יירשה ותנתן לו ויירשה\"\u0004 — \u0003זו היא מתנה באמצע. ו\u0004יש לסייג הלכה זו:","\u0003דוקא\u0004 שאמר לשונות אלה של ירושה ומתנה \u0003באדם אחד ושדה אחת, אבל\u0004 אם אמר \u0003באדם אחד ושתי שדות\u0004 (כגון \"יירש ראובן שדה פלונית ותינתן לו שדה אלמונית\"), או \u0003שדה אחת ושני בני אדם\u0004 (כגון \"יירש ראובן חצי שדה זו, ותינתן לשמעון מחציתה האחרת\") — \u0003לא,\u0004 שאנו אומרים שמה שנאמר בלשון מתנה — יינתן כדבריו, אך מה שאמר בלשון ירושה אינו חל.","\u0003ר' אלעזר אומר: אפילו\u0004 בזמן שאמר על \u0003אדם אחד ושתי שדות,\u0004 או שאמר על \u0003שדה אחת ושני בני אדם,\u0004 גם כן דבריו קיימים, לפי שמכל מקום הזכיר לשון מתנה לגבי אותו דבר שהזכיר בו לשון ירושה, \u0003אבל בשתי שדות ושני בני אדם\u0004 — \u0003לא,\u0004 שיש כאן שתי הוראות על שני דברים שונים, ובכל אחד יש לדון לפי עניינו.","ובענין זה מסופר, \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבין\u0004 מארץ ישראל לבבל, \u0003אמר:\u0004 מי שאמר \u0003\"תנתן שדה פלונית לפלוני, ויירש פלוני\u0004 אחר \u0003שדה פלונית\u0004 אחרת \u0003\",\u0004 במקרה זה \u0003ר' יוחנן אומר: קנה\u0004 גם זה שקיבל שדה בלשון ירושה, \u0003ר' אלעזר אומר: לא קנה.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרבין: אנחתת לן חדא ואתקפת לן חדא\u0004 \u0005[הנחת,\u0006 הקלת \u0005לנו\u0006 בשמועה \u0005אחת\u0006 שהבאת, \u0005והקשית עלינו\u0006 ב\u0005אחת],\u0006 שכן \u0003בשלמא\u0004 \u0005[נניח]\u0006 מדברי \u0003ר' אלעזר\u0004 על דברי \u0003ר' אלעזר לא קשיא\u0004 \u0005[אינו קשה],\u0006 כי אפשר לומר: \u0003כאן\u0004 שאמר שקנה, מדובר \u0003באדם אחד ושתי שדות,\u0004 ואילו \u0003כאן\u0004 שאמר שיש אופן שלא קנה — מדובר \u0003בשני בני אדם ושתי שדות.\u0004","\u0003אלא\u0004 מדברי \u0003ר' יוחנן\u0004 על דברי \u0003ר' יוחנן קשיא\u0004 \u0005[קשה],\u0006 שהרי לעיל אמר רב דימי בשמו שרק באדם אחד ושדה אחת דבריו קיימים, ואילו לדבריך, אף בשני בני אדם ובשתי שדות דבריו קיימים!","השיב לו רבין: בדבר זה \u0003אמוראי נינהו\u0004 \u0005[\u0006מחלוקת \u0005אמוראים\u0006 היא\u0005]\u0006 של רב דימי ושלי, \u0003ואליבא\u0004 \u0005[ועל פי שיטתו]\u0006 של \u0003ר' יוחנן.\u0004","והביא רבין דעה נוספת בענין זה, \u0003וריש לקיש אמר: לא קנה\u0004 בשני אנשים ושתי שדות \u0003עד שיאמר \"פלוני ופלוני יירשו שדה פלונית ופלונית שנתתים להם במתנה ויירשום\".\u0004","ומעירים: דבר זה בענין לשון מתנה וירושה באנשים שונים ובשדות שונים, שנחלקו בו אמוראי ארץ ישראל, שנוי גם \u0003בפלוגתא\u0004 \u0005[במחלוקת]\u0006 של אמוראי בבל. \u0003אמר רב המנונא: לא שנו\u0004 שכשמשתמש גם בלשון מתנה יכול להרבות לאחד מבניו, \u0003אלא\u0004 ב\u0003אדם אחד ושדה אחת,\u0004 \u0003אבל\u0004 ב\u0003אדם אחד ושתי שדות,\u0004 או ב\u0003שדה אחת ושני בני אדם\u0004 — \u0003לא. ורב נחמן אמר: אפילו\u0004 ב\u0003אדם אחד ושתי שדות,\u0004 וכן ב\u0003שדה אחת ושני בני אדם\u0004 אם אמר לשון מתנה, \u0003אבל\u0004 ב\u0003שתי שדות ושני בני אדם\u0004 — \u0003לא. ו\u0004אילו \u0003רב ששת אמר: אפילו\u0004 ב\u0003שתי שדות ושני בני אדם.\u0004","\u0003אמר רב ששת: מנא אמינא לה\u0004 \u0005[מנין אני אומר את\u0006 דעתי \u0005זו]?\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 שכיב מרע, או היוצא לדרך רחוקה, \u0003האומר\u0004 לאפוטרופוסים: \u0003\"תנו שקל לבני ב\u0004כל \u0003שבת\u0004 (שבוע) \u0003\"\u0004להוצאותיהם, \u0003וראוין\u0004 הבנים לפי צרכיהם \u0003ליתן\u0004 להם \u0003סלע,\u0004 שהוא שני שקלים, לכל שבוע — \u0003נותן להן\u0004 האפוטרופוס \u0003סלע. ואם אמר \"אל תתנו להן אלא שקל\",\u0004 ומשמע שהקפיד על קיום דבריו בדיוק — \u0003אין נותנין להן אלא שקל\u0004 אף שצרכיהם מרובים מכדי שקל לשבוע. \u0003ואם אמר \"אם מתו\u0004"],["\u0003יירשו אחרים תחתיהם\"\u0004 (ולא בני בניו), \u0003בין שאמר \"תנו\u0004 שקל \u0003\",\u0004 \u0003בין שאמר \"אל תתנו\u0004 אלא שקל \u0003\"\u0004— \u0003אין נותנין להן אלא שקל,\u0004 שהרי אם מוסיפים להם — ממעטים בכך מחלקם של אותם האחרים. ומצוואתו נראה שדעתו לתת לאחרים כל מה שנותר מאותה קיצבה.","ומכאן נלמד לענייננו, \u0003והא הכא\u0004 \u0005[והרי כאן]\u0006 ש\u0003כשתי שדות וכשני בני אדם דמי\u0004 \u0005[נחשב\u0006 הדבר\u0005],\u0006 שהרי הוא נותן חלק מרכושו לבניו בלשון מתנה, וחלק אחר לאחרים בלשון ירושה, \u0003וקתני דקני\u0004 \u0005[ושנה שקונה]\u0006 בכך לאחרים! והרי זה סיוע לדברי רב ששת, ומכאן גם קושיה לשיטות האחרות.","ומשיבים: \u0003הוא,\u0004 רב ששת, \u0003מותיב לה\u0004 \u0005[מקשה\u0006 את הקושיה \u0005הזו],\u0006 \u0003והוא\u0004 עצמו \u0003מפרק לה\u0004 \u0005[מתרץ אותה],\u0006 שמה שנאמר \"יירשו אחרים\" עוסק דווקא \u0003ב\u0004מי ש\u0003ראוי ליורשו,\u0004 ואם כן, אין כאן צורך כלל בלשון מתנה. \u0003ו\u0004כשיטת \u0003ר' יוחנן בן ברוקה היא\u0004 ברייתא זו, שלדעתו רשאי להוריש את כל נכסיו, ואף בלשון ירושה, לכל הראוי ליורשו.","\u0003אמר רב אשי, תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר ממה ששנינו במקור אחר: אם אמר \u0003\"נכסי לך\u0004 אחרי מותי, שתשתמש בהם כל ימי חייך, \u0003ואחריך\u0004 (אחרי מותך) \u0003יירש פלוני, ואחרי אחריך יירש פלוני\",\u0004 כש\u0003מת ראשון\u0004 — \u0003קנה שני, מת שני\u0004 — \u0003קנה שלישי, ואם מת\u0004 ה\u0003שני בחיי\u0004 ה\u0003ראשון\u0004 — אין הנכסים עוברים לאחר מות הראשון לשלישי, אלא \u0003יחזרו נכסים ליורשי ראשון,\u0004 כי השלישי זוכה רק מכחו של השני, ושני זה הרי לא ירש דבר.","\u0003והא הכא\u0004 \u0005[והרי כאן]\u0006 ש\u0003כשתי שדות ושני בני אדם דמי\u0004 \u0005[נחשב\u0006 הדבר\u0005],\u0006 שלראשון נתן בלשון מתנה (\"נכסי לך\") ולשני בלשון ירושה (\"ואחריך יירש\"), \u0003וקתני\u0004 \u0005[ושנה]\u0006 ש\u0003קנה\u0004 אף השני קנין גמור!","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 כי \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 מדובר \u0003ב\u0004מי שהיה \u0003ראוי ליורשו, ו\u0004שיטת \u0003ר' יוחנן בן ברוקה היא,\u0004 \u0003אי הכי\u0004 \u0005[אם כך],\u0006 מדוע אם \u0003מת\u0004 ה\u0003שני קנה\u0004 ה\u0003שלישי?\u0004","\u0003הא\u0004 \u0005[הרי]\u0006 \u0003שלח רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב עויא: לדברי\u0004 \u0003ר' יוחנן בן ברוקה,\u0004 אם אומר \u0003\"נכסי לך ואחריך לפלוני\", וראשון ראוי ליורשו\u0004 — \u0003אין לשני במקום ראשון כלום,\u0004 אלא יורשיו של הראשון מקבלים, \u0003שאין זה\u0004 (הביטוי \"נכסי לך\") \u0003לשון מתנה אלא לשון ירושה, וירושה אין לה הפסק\u0004 אלא עוברת מדור לדור! אלא לא ניתן להעמיד ברייתא זו לשיטתו.","ואם כן הרי זו \u0003תיובתא דכולהו\u0004 \u0005[קושיה חמורה על כולם]\u0006 על כל החכמים שאמרו שאינו יכול להסתמך על לשון מתנה בשני שדות ושני בני אדם. ומסכמים: אכן \u0003תיובתא\u0004 \u0005[קושיה חמורה\u0006 היא\u0005].\u0006","ושואלים: \u0003לימא נמי תיהוי תיובתיה\u0004 \u0005[האם לומר גם כן\u0006 ש\u0005תהא\u0006 זו \u0005קושיה]\u0006 גם על שיטת \u0003ריש לקיש?\u0004 שהרי גם הוא עמד על כך (בעמוד הקודם) שלשון מתנה תיאמר על שניהם. ותוהים: \u0003ותסברא\u0004 \u0005[ו\u0006כי \u0005יכול אתה לסבור כן]\u0006 שיידחו דבריו? \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר רבא: הלכתא כותיה\u0004 \u0005[הלכה כשיטתו]\u0006 של \u0003ריש לקיש בהני תלת\u0004 \u0005[בשלוש\u0006 הלכות \u0005אלה]:\u0006 בענין קנין פירות, ובענין חליצת מעוברת, ובענין זה של מתנה וירושה!","ומשיבים: \u0003לא קשיא\u0004 \u0005[אינו קשה]:\u0006 \u0003כאן\u0004 שמועילה לשון מתנה גם למי שנאמרה בו לשון ירושה — הרי זה \u0003בתוך כדי דבור,\u0004 לפי שהן נחשבות כדיבור אחד, \u0003כאן\u0004 שצריך לשון מתנה בשניהם — הרי זה כשהפסיק בין שניהם \u0003לאחר כדי דבור.\u0004","\u0003והלכתא\u0004 \u0005[והלכה]\u0006 כללית: \u0003כל תוך כדי דבור כדבור דמי\u0004 \u0005[נחשב],\u0006 \u0003לבר\u0004 \u0005[חוץ]\u0006 \u0003מעבודה זרה,\u0004 שאם אמר שהוא מקבל על עצמו עבודה זרה, הרי זה מתחייב מיתה אף על פי שחזר בו תוך כדי דיבור,"],["\u0003וקדושין\u0004 שאם קידש אשה כראוי, אפילו חזר בו תוך כדי דיבור — אין חזרתו מועילה.","\u0003האומר \"איש פלוני יירשני\" במקום שיש\u0004 לו \u0003בת\u0004 למוריש, או האומר \u0003\"בתי תירשני\" במקום שיש בן\u0004 — \u0003לא אמר כלום,\u0004 כיון \u0003שהתנה על מה שכתוב בתורה\u0004 שנאמר בה סדר הירושה הראוי. \u0003ר' יוחנן בן ברוקה אומר: אם אמר\u0004 דבר זה \u0003על מי שראוי ליורשו\u0004 — \u0003דבריו קיימין, ו\u0004אם אמר \u0003על מי שאין ראוי לו ליורשו\u0004 — \u0003אין דבריו קיימין.\u0004","ומדייקים בדברי המשנה: \u0003טעמא\u0004 \u0005[הטעם\u0006 דווקא\u0005]\u0006 במקרה שאמר על \u0003אחר במקום\u0004 שיש \u0003בת ו\u0004על \u0003בת במקום\u0004 שיש \u0003בן,\u0004 שכן אינם ראויים לירש במקום אלה, לא אמר כלום, \u0003הא\u0004 \u0005[אבל]\u0006 אם היה אומר על \u0003בן בין הבנים\u0004 שיירש הכל, \u0003ו\u0004כן על \u0003בת\u0004 אחת \u0003בין הבנות\u0004 — \u0003דבריו קיימין.\u0004 ואולם \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה\u0006 של המשנה\u0005],\u0006 \u0003ר' יוחנן בן ברוקה אומר: אם אמר על מי שראוי ליורשו\u0004 — \u0003דבריו קיימין.\u0004 ולפי זה \u0003היינו\u0004 \u0005[הרי זה]\u0006 בדיוק שיטת ה\u0003תנא קמא\u0004 \u0005[הראשון],\u0006 ובמה נחלקו?","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 ש\u0003ר' יוחנן בן ברוקה אפילו\u0004 על \u0003אחר במקום בת ובת במקום בן קאמר\u0004 \u0005[הוא אומר]\u0006 שיכול להוריש להם, הואיל והם ראויים ליורשו כשימות היורש הנוכחי (למרות שעכשיו אינם ראויים), ובכך חלק על תנא קמא. \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' ישמעאל בנו של\u0004 \u0003ר' יוחנן בן ברוקה אומר: לא נחלקו אבא וחכמים על אחר במקום בת ו\u0004כן \u0003בת במקום בן,\u0004 שגם אבא סבור \u0003שלא אמר כלום.\u0004","\u0003על מה נחלקו?\u0004 — \u0003על בן בין הבנים ובת בין הבנות, שאבא אומר: יירש, וחכמים אומרים: לא יירש!\u0004","ומתרצים: \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 תירוץ זה: \u0003מדקאמר\u0004 \u0005[מ\u0006תוך \u0005שאמר]\u0006 ר' ישמעאל \u0003\"לא נחלקו\", מכלל\u0004 דבריו אתה למד שהוא חולק על התנא של משנתנו, שה\u0003תנא קמא סבר\u0004 \u0005[הראשון,\u0006 במשנתנו, \u0005סבור]\u0006 \u0003נחלקו.\u0004","\u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 תירוץ לשאלה באופן זה: \u0003כוליה\u0004 \u0005[כולו],\u0006 כל המשנה שלנו שיטת \u0003ר' יוחנן בן ברוקה היא, וחסורי מחסרא והכי קתני\u0004 \u0005[וחסרה\u0006 המשנה, \u0005וכך\u0006 צריך \u0005לשנותה]:\u0006 \u0003האומר \"איש פלוני יירשני\" במקום שיש בת,\u0004 או שאמר \u0003\"בתי תירשני\" במקום שיש בן\u0004 — \u0003לא אמר כלום; הא\u0004 \u0005[הרי]\u0006 \u0003בת בין הבנות ובן בין הבנים, אם אמר\u0004 ש\u0003יירש\u0004 את \u0003כל נכסיו\u0004 — \u0003דבריו קיימין, ש\u0004כן \u0003ר' יוחנן\u0004 (בן ברוקה) \u0003אומר: אם אמר על מי שראוי ליורשו\u0004 — \u0003דבריו קיימין.\u0004","ובפסק ההלכה בענין זה \u0003אמר רב יהודה אמר שמואל: הלכה כר' יוחנן בן ברוקה. וכן אמר רבא: הלכה כר' יוחנן בן ברוקה.\u0004","\u0003אמר רבא: מאי טעמיה\u0004 \u0005[מה טעמו]\u0006 של \u0003ר' יוחנן בן ברוקה?\u0004 — \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 במשפט הירושה: \u0003\"והיה ביום הנחילו את בניו\"\u0004 (דברים כא, טז), ומכאן אנו למדים ש\u0003התורה נתנה רשות לאב להנחיל לכל מי שירצה\u0004 מבניו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: הא\u0004 \u0005[\u0006דבר \u0005זה]\u0006 \u0003מ\"לא יוכל לבכר\"\u0004 (דברים כא, טז) \u0003נפקא\u0004 \u0005[יוצא,\u0006 נלמד\u0005],\u0006 שהכתוב אוסר להעביר את הבכור מבכורתו, וממה שנזכר דווקא איסור זה יש ללמוד שיכול הוא לשנות את חלקם של בנים אחרים!","ומשיבים: \u0003ההוא מיבעי ליה לכדתניא\u0004 \u0005[אותו\u0006 פסוק \u0005נצרך\u0006 הוא \u0005לו לכפי ששנינו\u0006 בברייתא\u0005],\u0006 \u0003אבא חנן אמר משום\u0004 (בשם) \u0003ר' אליעזר:\u0004"],["\u0003מה תלמוד לומר \"לא יוכל לבכר\"\u0004 (דברים כא, טז)?","— \u0003לפי שנאמר: \"והיה ביום הנחילו את בניו\"\u0004 (דברים כא, טז), \u0003שיכול\u0004 אתה לומר כך, \u0003והלא דין\u0004 (קל וחומר) \u0003הוא: ומה\u0004 בן \u0003פשוט\u0004 (שאינו בכור) \u0003שיפה כחו\u0004 בירושה, ובמה? — \u0003שנוטל\u0004 חלקו בירושה גם \u0003ב\u0004דבר שהוא \u0003ראוי\u0004 לבוא ליד אביו, אף שאיננו ברשות אביו בעת מותו, \u0003כ\u0004נוטל חלק \u0003במוחזק\u0004 כבר ברשותו של אביו — \u0003התורה נתנה רשות לאב להנחיל לכל מי שירצה,\u0004 ולמנוע את הבן הפשוט מנחלתו, \u0003בכור שהורע כחו, שאינו נוטל\u0004 חלק בכורתו \u0003בראוי כבמוחזק\u0004 — \u0003לא כל שכן\u0004 שיכול האב להפקיעו מבכורתו? — \u0003תלמוד לומר: \"לא יוכל לבכר\".\u0004","ומצד שני: \u0003ויאמר\u0004 הכתוב רק \u0003\"לא יוכל לבכר\", מה תלמוד לומר \"והיה ביום הנחילו את בניו\"?\u0004","— \u0003שיכול, והלא דין\u0004 \u0003הוא: ומה בכור שהורע כחו, שאינו נוטל בראוי כבמוחזק\u0004 — \u0003אמרה תורה: \"לא יוכל לבכר\", פשוט שיפה כחו\u0004 מן הבכור, \u0003שנוטל בראוי כבמוחזק\u0004 — \u0003לא כל שכן\u0004 שאינו יכול להעבירו מנחלתו!","\u0003תלמוד לומר: \"והיה ביום הנחילו את בניו\",\u0004 לומר: \u0003התורה נתנה רשות לאב להנחיל לכל מי שירצה.\u0004 הרי שאין די ב\"לא יוכל לבכר\" ללמד שיכול האב להנחיל לכל מי שירצה מבניו.","ועוד בפסק ההלכה בענין זה, מביאים: \u0003אמר\u0004 \u0003ר' זריקא אמר\u0004 \u0003ר' אמי אמר\u0004 \u0003ר' חנינא אמר רבי: הלכה כר' יוחנן בן ברוקה. אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' אבא\u0004 לר' זריקא: \u0003\"הורה\" איתמר\u0004 \u0005[נאמר]\u0006 כלומר, הורה רבי כר' יוחנן בן ברוקה במעשה שבא לפניו.","ושואלים: \u0003במאי קמיפלגי\u0004 \u0005[במה הם חלוקים],\u0006 שהרי בסופו של דבר הם מסכימים להלכה ולמסורת, ומדוע מדקדק ר' אבא לומר שהורה רבי כן? \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 ר' זריקא, \u0005סבור]:\u0006 \u0003הלכה עדיפא\u0004 \u0005[עדיפה,\u0006 גדולה יותר\u0005],\u0006 שאם נמסר לנו שכך פסק הלכה עקרונית וכללית בענין, הרי זה חשוב יותר מאשר אם נמסר לנו שכך הורה למעשה במקרה מסויים. \u0003ומר סבר\u0004 \u0005[וחכם זה סבור]:\u0006 \u0003מעשה רב\u0004 (גדול יותר) שאם נהג חכם והורה למעשה באותו אופן, הרי זה עדיף מאשר פסק הלכה עקרוני.","ובאותו ענין \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אין למדין הלכה לא מפי\u0004 \u0003תלמוד,\u0004 ממה שהרב מלמד, \u0003ולא מפי\u0004 \u0003מעשה,\u0004 שרואה שכך עשו מעשה, \u0003עד שיאמרו לו\u0004 \u0003הלכה למעשה\u0004 מוגדר ומסויים, ששאל עליו והורו לו הלכה בו. ואף אם \u0003שאל ואמרו לו הלכה למעשה\u0004 — \u0003ילך ויעשה מעשה\u0004 כמו שהורו לו, \u0003ובלבד שלא ידמה\u0004 הוראה זו ויחיל אותה מדעת עצמו אף על דברים אחרים שעליהם לא שאל במפורש.","ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"ובלבד שלא ידמה\"? והא\u0004 \u0005[והרי]\u0006 \u0003כל התורה כולה דמויי מדמינן לה\u0004 \u0005[מדמים אנו אותה\u0006 מדבר לדבר\u0005],\u0006 שכל לימודנו בהלכה אינו אלא בדרך של השוואת דבר מסופק לדבר שכבר נקבעה בו הלכה!","\u0003אמר רב אשי, הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003ובלבד שלא ידמה בטרפות.\u0004 שאף שבהלכות אחרות אכן מדמים דבר לדבר, בדיני טריפות — להגדיר מהי טריפה, שעומדת למות ואסורה באכילה — אל ידמה.","\u0003דתניא\u0004 \u0005[\u0006וכפי \u0005ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003אין אומרים בטרפות זו דומה לזו,\u0004 אלא כל אחת יש לה דין לעצמה. ומוסיפים: \u0003ואל תתמה\u0004 שכן הוא, \u0003שהרי\u0004 פעמים באותו איבר עצמו אף שאם \u0003חותכה מכאן ומתה,\u0004 מכל מקום אם \u0003חותכה מכאן וחיתה,\u0004 ואין הבהמה נטרפת בכך.","ועוד בענין זה, \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' אסי לר' יוחנן: כי אמר לן מר\u0004 \u0005[כאשר אדוני אומר לנו]\u0006 \u0003\"הלכה הכי\u0004 \u0005[כך]\u0006 \u0003\",\u0004 \u0003נעביד\u0004 \u0005[נעשה]\u0006 \u0003מעשה? אמר\u0004 ר' יוחנן: \u0003לא תעבידו\u0004 \u0005[תעשו]\u0006 \u0003עד דאמינא\u0004 \u0005[שאני אומר]\u0006 \u0003\"הלכה למעשה\".\u0004","\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רבא לרב פפא ולרב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע: כי אתי פסקא דדינא דידי לקמייכו וחזיתו ביה פירכא\u0004 \u0005[כאשר בא פסק דין שלי לפניכם ואתם רואים בו קושי],\u0006 \u0003לא תקרעוהו\u0004 מיד כדי לבטלו \u0003עד דאתיתו לקמאי\u0004 \u0005[שאתם באים לפני]\u0006 לדון עליו, \u0003אי אית\u0004 \u0005[אם יש]\u0006 \u0003לי טעמא\u0004 \u0005[טעם\u0006 בדבר\u0005]\u0006 — \u0003אמינא לכו\u0004 \u0005[אומר לכם],\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003ל א\u0004 — \u0003הדרנא\u0004 \u0005[אחזור]\u0006 \u0003בי\u0004 ממה שפסקתי. ואם יבוא פסק דין שלי לפניכם \u0003לאחר מיתה,\u0004 שאז אין אתם יכולים לדון אתי עליו — \u0003לא מיקרע תקרעוהו\u0004 \u0005[אל תקרעו אותו],\u0006 \u0003ו\u0004אולם \u0003מגמר נמי לא תגמרו מיניה\u0004 \u0005[ללמוד גם כן אל תלמדו ממנו].\u0006 והסביר את דבריו אלה הנראים כסותרים זה את זה: \u0003לא מיקרע תקרעיניה\u0004 \u0005[אל תקרעו אותו]\u0006 — \u0003דאי הואי התם דלמא הוה אמינא לכו טעמא\u0004 \u0005[שאם הייתי שם, שמא הייתי אומר לכם טעם]\u0006 ומסביר את דבריי עד שהייתם מקבלים אותם,"],["ואולם \u0003מגמר נמי לא תגמרו מיניה\u0004 \u0005[ללמוד גם כן אל תלמדו ממנו]\u0006 לעשות ככתוב בו, למרות שמתקשים אתם בפסק זה, שכן \u0003אין\u0004 לו \u0003לדיין אלא מה שעיניו רואות,\u0004 ואתם צריכים לעשות לפי שיקול דעתכם, כפי הנראה לכם נכון.","וחוזרים לדון בשיטת ר' יוחנן בן ברוקה שבמשנתנו, במי שאומר שאחד מבניו יירשנו, שדבריו קיימים. \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבא: בבריא היאך?\u0004 אם אדם בריא מוריש את כל נכסיו לאחד מבניו, מה הדין? האם \u0003כי קאמר\u0004 \u0005[כאשר אמר]\u0006 \u0003ר' יוחנן בן ברוקה\u0004 את הלכתו זו — אמר זאת דווקא \u0003בשכיב מרע, דבר אורותי\u0004 \u0005[שבן הורשה]\u0006 \u0003הוא,\u0004 שהוא עומד למות ומחלק ירושתו, ועליו נאמר \"ביום הנחילו את בניו\" — שהוא יכול להנחיל למי מהם שירצה, \u0003אבל בבריא\u0004 שנותן משום ירושה — \u0003לא. או דלמא\u0004 \u0005[שמא]\u0006 \u0003אפילו בבריא נמי\u0004 \u0005[גם כן]\u0006 נאמרה הלכה זו?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב משרשיא לרבא: תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לשאלתך ממה ש\u0003אמר לו\u0004 \u0003ר' נתן\u0004 הבבלי \u0003לרבי,\u0004 ר' יהודה הנשיא שערך וניסח את המשנה: \u0003שניתם משנתכם כר' יוחנן בן ברוקה! דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]\u0006 במסכת כתובות: \u0003לא כתב לה\u0004 הבעל לאשתו בכתובתה \u0003\"בנין דיכרין דיהוין ליך מינאי, אינון ירתון\u0004 \u0005[בנים זכרים שיהיו לך ממני, הם יירשו]\u0006 את \u0003כסף כתובתיך יותר על חולקיהון\u0004 \u0005[חלקיהם]\u0006 ש\u0003עם אחוהון\u0004 \u0005[אחיהם]\u0006 \u0003\"\u0004שאם הוא ימות אחריה ויהיו לו בנים גם מאשה אחרת, בניה של אשה זו ירשו תחילה את הכלול בכתובתה, ורק לאחר מכן יחלקו עם שאר הבנים בשאר הנכסים. גם אם לא נכתב דבר זה בכתובה — \u0003חייב,\u0004 \u0003שתנאי בית דין הוא,\u0004 תקנה שתיקנו חכמים שיטלו הבנים כתובת אימם. ומכאן שלדעתך הלכה כדברי ר' יוחנן בן ברוקה, שרשאי האב להוסיף לבן מסויים בירושה יתר על חלקו.","\u0003ואמר לו רבי:\u0004 אין אנו שונים בדבר זה \"ירתון (יירשו) בנייך כסף כתובתיך\", אלא \u0003\"יסבון\u0004 (יטלו) בניך כסף כתובתיך \u0003\"\u0004\u0003תנן\u0004 \u0005[שנינו],\u0006 ובלשון מתנה יכול האב להרבות ולמעט בירושה לדעת כולם, כפי ששנינו במשנה הקודמת (לעיל בבא בתרא קכו,ב).","ומסופר, לאחר מכן חזר \u0003ואמר רבי: ילדות\u0004 (שטות של ילד) \u0003היתה בי והעזתי פני בנתן הבבלי\u0004 לומר דבר שאינו נכון. ומדוע אין זה נכון? \u0003אלא דקיימא לן\u0004 \u0005[ש\u0006הרי \u0005מוחזק בידינו]:\u0006 \u0003בנין דכרין לא טרפא ממשעבדי\u0004 \u0005[\u0006כתובת \u0005בנים זכרים אינה טורפת מ\u0006נכסים \u0005משועבדים],\u0006 שאין הבנים יכולים לגבות את דמי כתובת אימם מנכסים שכבר מכר אביהם לאחרים, ואולם \u0003אי סלקא דעתך \"יסבון\" תנן, אמאי\u0004 \u0005[אם עולה על דעתך\u0006 ש\u0005\"יטלו\" שנינו, מדוע]\u0006 אם כן \u0003לא טרפא ממשעבדי\u0004 \u0005[יטרפו\u0006 הבנים \u0005מ\u0006נכסים \u0005משועבדים]?\u0006 שאם הוא שטר מתנה — הרי הוא חל מרגע שנכתב, ואם כן מתנתם של הבנים קודמת לנכסים שמכר! \u0003אלא שמע מינה \"ירתון\" תנן\u0004 \u0005[למד מכאן\u0006 ש\u0005\"יירשו\" שנינו],\u0006 כלומר, לאחר מותו, וכיון שכבר מכר האב שוב אין לבנים חלק בהם.","ומעתה, \u0003מאן שמעת ליה דאית ליה האי סברא\u0004 \u0005[מי שמעת אותו שיש לו סברה זו]\u0006 שיכול לחלק ירושה לחלק מבניו כפי שירצה — \u0003ר' יוחנן בן ברוקה,\u0004 ומשנה זו אם כן לשיטתו היא. \u0003ושמע מינה\u0004 \u0005[ולמד מכאן]\u0006 שדבריו נאמרו \u0003אפילו בבריא,\u0004 שהרי כתובה כותב אדם כשהוא נושא אשה, ולא כשהוא שכיב מרע. ונפתרה איפוא שאלתו של רבא.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לאביי:\u0004 כיצד יש להוכיח מן הנוסח \"ירתון\" שמשנה זו לשיטת ר' יוחנן בן ברוקה נאמרה? והרי \u0003בין למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 שהנוסח הוא \u0003\"יסבון\"\u0004 \u0005[\"יטלו\"],\u0006 \u0003ובין למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 שהנוסח הוא \u0003\"ירתון\"\u0004 \u0005[\"יירשו\"],\u0006 יש לשאול: כיצד מקנה אדם לבניו עוד בזמן נישואיו כתובת \"בנין דכרין\"? \u0003הא\u0004 \u0005[הרי]\u0006 כלל הוא ש\u0003אין אדם מקנה דבר שלא בא לעולם.\u0004","\u0003ואפילו ל\u0004דעת \u0003ר' מאיר\u0004 ש\u0003אמר: אדם מקנה דבר שלא בא לעולם, הני מילי\u0004 \u0005[דברים אלה\u0006 אמורים\u0005]\u0006 כשהוא מקנה אותו \u0003לדבר\u0004 (למי) \u0003שישנו בעולם, אבל לדבר שאינו בעולם\u0004 — \u0003לא,\u0004 וכשנושא אשה הרי אין בניה עדיין בעולם!","\u0003אלא\u0004 בהכרח עליך לומר ש\u0003תנאי בית דין שאני\u0004 \u0005[שונה],\u0006 שיש כח ביד חכמים להקנות דבר למרות שאינו בגדר דיני המתנה הרגילים. \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 לענין נוסח הכתובה נאמר: \u0003תנאי בית דין שאני\u0004 \u0005[שונה],\u0006 ואף לדעת חכמים הסבורים שאינו יכול להוריש לחלק מבניו יותר מן האחרים, תיקנו חכמים שיוכל לעשות כן. ואם כן, אין הוכחה כלל שנוסח המשנה הוא כדעת ר' יוחנן בן ברוקה!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 אביי: גם אם תוקף הדבר הוא מפני תנאי בית דין, מכל מקום עיקר הראיה היא \u0003משום דקא מפיק לה\u0004 \u0005[שהוא מוציא זאת]\u0006 \u0003בלשון \"ירתון\"\u0004 \u0005[\"יירשו\"],\u0006 שאם משתמשים בלשון זו ולא בלשון מתנה, משמע שאף במקרים אחרים יכול להוריש לבניו כפי שירצה, ומכאן ששיטת ר' יוחנן בן ברוקה היא.","\u0003הדר\u0004 \u0005[חזר]\u0006 ו\u0003אמר אביי: לאו מילתא היא דאמרי\u0004 \u0005[אין זה דבר\u0006 נכון מה \u0005שאמרתי],\u0006 כי גם לשיטת חכמים החולקים עליו, יש טעם לשימוש בנוסח \"ירתון\", לפי \u0003דתנן\u0004 \u0005[ששנינו]\u0006 באותה משנה, מיד לאחר מכן: \u0003לא כתב לה\u0004 בתנאי כתובתה \u0003\"בנן נוקבן דיהויין ליכי מינאי יהויין יתבן\u0004 \u0005[בנות נקבות שיהיו לך ממני יהיו יושבות]\u0006 \u0003בביתי ויתזנן מנכסאי\u0004 \u0005[ויזונו מנכסי]\u0006 \u0003עד דתילקחן לגוברין\"\u0004 \u0005[שילקחו לאנשים]\u0006 — \u0003חייב\u0004 מכל מקום לפרנס את הבנות, לפי \u0003שהוא תנאי בית דין.\u0004","אם כן נמצא שיש בכתובה שני תנאים צמודים, \u0003והוה\u0004 \u0005[והינו]\u0006 כמוריש לשני אנשים, \u0003לזה במתנה ולזה בירושה, וכל\u0004 דבר שהוא \u0003לזה בירושה ולזה במתנה\u0004 — \u0003אפילו רבנן מודו\u0004 \u0005[חכמים מודים]\u0006 שלשון מתנה מתייחסת לכל, ומתחלקים נכסיו כפי שציוה, גם אם חילק למי שאינו מיורשיו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב נחומי, ואית\u0004 \u0005[ויש\u0006 שאומרים\u0005]\u0006 ש\u0003אמר\u0004 זאת \u0003רב חנניה בר מניומי לאביי:\u0004"],["\u0003ממאי\u0004 \u0005[ממה]\u0006 מסיק אתה \u0003דבחד בי דינא איתקון\u0004 \u0005[שבבית דין אחד נתקנו]\u0006 שתי התקנות, גם עבור בנים זכרים וגם לגבי בנות, שמשום כך אתה מבין שלשון מתנה וירושה נאמרות כהמשך אחד? \u0003דלמא בתרי בי דינא איתקון\u0004 \u0005[שמא בשני בתי דין נתקנו]\u0006 ואם כן, הירושה והמתנה באות מכוחם של שני תנאים נפרדים!","ומשיבים: \u0003לא סלקא דעתך\u0004 \u0005[יעלה על דעתך]\u0006 לומר כן, \u0003דקתני רישא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 \u0005בתחילה],\u0006 במסכת כתובות, קודם למשנה זו: \u0003זה מדרש דרש\u0004 \u0003ר' אלעזר בן עזריה לפני חכמים בכרם ביבנה:\u0004 בתנאי כתובה תיקנו חכמים את שני הדברים, ש\u0003הבנים יירשו\u0004 את כתובת אימם \u0003והבנות יזונו\u0004 מנכסי האב, ויש ללמוד מזה על זה: \u0003מה הבנים אינן יורשין אלא לאחר מיתת אביהם, אף בנות לא יזונו אלא לאחר מיתת אביהן;\u0004 ומעתה,","\u0003אי אמרת בשלמא בחד בי דינא איתקון\u0004 \u0005[נניח אם אתה אומר\u0006 ש\u0005בבית דין אחד נתקנו],\u0006 \u0003היינו דילפינן\u0004 \u0005[זהו\u0006 הטעם \u0005שאנו למדים]\u0006 \u0003תקנה מתקנה,\u0004 מתוך הנחה שאותו בית דין מתקן תקנות במתכונת דומה. \u0003אלא אי אמרת בתרי בי דינא איתקון\u0004 \u0005[אם אתה אומר\u0006 ש\u0005בשני בתי דין נתקנו]\u0006 בשתי תקופות שונות, \u0003היכי ילפינן\u0004 \u0005[כיצד אנו למדים]\u0006 \u0003תקנה מתקנה?\u0004","ודוחים: \u0003ממאי\u0004 \u0005[ממה]\u0006 אתה מסיק זאת? \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003לעולם אימא\u0004 \u0005[\u0006יכול \u0005אני לומר]\u0006 \u0003לך\u0004 כי \u0003בתרי בי דינא איתקון\u0004 \u0005[בשני בתי דין נתקנו],\u0006 \u0003ובי דינא בתרא תקון כבי דינא קמא\u0004 \u0005[ובית הדין האחרון תיקן כ\u0006פי שתיקן \u0005בית הדין הראשון]\u0006 \u0003כי היכי\u0004 \u0005[כך]\u0006 ש\u0003לא תקשה תקנתא אתקנתא\u0004 \u0005[תהיה קושיה מתקנה על תקנה],\u0006 ולפיכך יכול היה ר' אלעזר בן עזריה ללמוד מתקנה אחת לאחרת. אך מצד שני, אין לראותן בהכרח כהמשך דברים אחד לענין לשון ירושה ומתנה.","\u0003אמר רב יהודה אמר שמואל:\u0004 שכיב מרע \u0003הכותב כל נכסיו לאשתו\u0004 — \u0003לא עשאה אלא אפוטרופא\u0004 (אפוטרופוסית),","כלומר, אנו מניחים שלא שלל את כל נכסיו מיורשיו, וכוונתו אינה אלא לעשותה אפוטרופסית על נכסיו, כדי לתת לה מעמד וכבוד אצל היורשים. ובעקבות הלכה זו דנים במקרים אחרים, ומקדימים: \u0003פשיטא\u0004 \u0005[פשוט\u0006 לנו\u0005]\u0006 גם כן, שאם כתב את כל נכסיו ל\u0003בנו הגדול\u0004 — אין כוונתו לתת לו הכל, ו\u0003לא עשאו אלא\u0004 \u0003אפוטרופוס\u0004 לכל הנכסים, ואין לו אלא חלקו בירושה. אבל אם כתב נכסיו ל\u0003בנו הקטן מאי\u0004 \u0005[מה]\u0006 הדין? האם גם כן מניחים אנו שעשאו אפוטרופוס על הנכסים. או שמא כיון שקטן הוא ואינו יכול להיעשות עכשיו אפוטרופוס, אולי אין מקום להניח שלכך התכוון האב, ונתן לו באמת כל נכסיו?","ומשיבים: \u0003איתמר\u0004 \u0005[נאמר]\u0006 על כך, \u0003רב חנילאי בר אידי אמר שמואל: אפילו\u0004 כתב ל\u0003בנו\u0004 ה\u0003קטן המוטל בעריסה\u0004 לא קנה את הנכסים, אלא רצה האב לעשותו אפוטרופוס כדי שיכבדוהו כשיגדל.","ועוד אומרים: \u0003פשיטא\u0004 \u0005[פשוט\u0006 לנו\u0005]\u0006 שאם כתב כל נכסיו ל\u0003בנו ואחר\u0004 — \u0003לאחר\u0004 התכוון לתת חצי \u0003במתנה, ובנו\u0004 התכוון לעשותו \u0003אפוטרופוס\u0004 על החצי האחר, ואם היו בנים נוספים מתחלק עמם בירושה. וכמו כן, אם כתב את כל נכסיו ל\u0003אשתו ואחר\u0004 — \u0003לאחר\u0004 התכוון לתת חצי נכסיו \u0003במתנה, ו\u0004את \u0003אשתו\u0004 עשה \u0003אפוטרופוס\u0004 על החצי השני.","וכן פשוט לנו הדין במי שכותב כל נכסיו ל\u0003אשתו ארוסה\u0004 שטרם נשאה לאשה, \u0003ו\u0004כן אם היתה זו \u0003אשתו גרושה\u0004 — הרי זה \u0003במתנה,\u0004 ולא עשאן אפוטרופוס, שבוודאי אין לו ענין לכבדן בפני יורשיו.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם,\u0006 ללומדים\u0005]:\u0006 אם כתב כל נכסיו ל\u0003בת אצל הבנים,\u0004 כלומר, כשיש לו גם בנים, או \u0003אשה אצל האחים,\u0004 כשלא היו לו בנים אלא רק אחים, או \u0003אשה אצל בני הבעל\u0004 שאינם בניה, \u0003מהו?\u0004 האם אנו דנים את הכתיבה הזאת כמתנה, או כאפוטרופסות?","\u0003אמר רבינא, משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא: בכולהו\u0004 \u0005[בכולם]\u0006 בכל הנשים המנויות כאן \u0003לא קנה,\u0004 לא קנתה האשה, אלא נעשתה אפוטרופוסית בלבד, \u0003לבר\u0004 \u0005[חוץ]\u0006 \u0003מאשתו ארוסה ואשתו גרושה.\u0004 זו היתה שיטה אחת בשם רבא. ואילו \u0003רב עוירא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא אמר: בכולהו קני\u0004 \u0005[בכולם קונה]\u0006 את הנכסים במתנה, \u0003לבר\u0004 \u0005[חוץ]\u0006 \u0003מהאשה אצל האחין ואשה אצל בני הבעל,\u0004 שרק באלה לא נתכוון אלא למנותן כאפוטרופוס."],["לאחר שאמרנו ששכיב מרע שכתב כל נכסיו לאשתו, לא עשאה אלא אפוטרופסית, \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבא: בבריא\u0004 שכתב כל נכסיו לאשתו, \u0003היאך\u0004 הדין? וצדדי השאלה: האם נאמר כי דווקא \u0003בשכיב מרע הוא דניחא ליה\u0004 \u0005[שנוח לו]\u0006 שתהיה אשתו אפוטרופסית, כדי \u0003דלישתמעון מלה\u0004 \u0005[שיישמעו דבריה]\u0006 ויכבדו אותה, \u0003אבל בבריא הא קאי איהו\u0004 \u0005[הרי עומד הוא]\u0006 ויכול לדאוג שיכבדוה כראוי, ולכן יש לומר שכוונתו באמת להקנות לה את כל הנכסים. \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003בריא נמי\u0004 \u0005[גם כן]\u0006 \u0003ניחא ליה דלישתמעון מלה מהשתא\u0004 \u0005[נוח לו שיישמעו דבריה\u0006 ויכבדו אותה כבר \u0005מעכשיו]?\u0006","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לבעיה זו ממה ששנינו בברייתא: \u0003הכותב פירות נכסיו לאשתו\u0004 — אם תתגרש או תתאלמן \u0003גובה כתובתה\u0004 שהתחייב לה משעת הנישואין \u0003מן הקרקע.\u0004 וכן אם כתב לה את הנכסים עצמם \u0003למחצה לשליש ולרביע\u0004 — \u0003גובה כתובתה מן השאר,\u0004 מן החלק שלא נתן לה במתנה.","\u0003כתב כל נכסיו לאשתו\u0004 בשטר מתנה, \u0003ויצא עליו שטר חוב\u0004 על מה שלווה לאחר נישואיו, קודם שכתב לה שטר מתנה זה, \u0003ר' אליעזר אומר: תקרע\u0004 שטר \u0003מתנתה ותעמוד על כתובתה,\u0004 ולא יוכל בעל החוב לגבות מן הנכסים, שהרי הכתובה מוקדמת לשטר החוב. \u0003וחכמים אומרים: תקרע כתובתה ותעמוד על מתנתה,\u0004 כי כשקיבלה את מתנת כל נכסיו ויתרה על זכותה לגבות את הכתובה מהם. ואולם כיון ששטר החוב קודם למתנה זו — נוטל בעל החוב את הנכסים, \u0003ונמצאת\u0004 האשה \u0003קרחת מכאן ומכאן,\u0004 כלומר, הפסידה גם את מתנתה וגם את גביית כתובתה.","\u0003ו\u0004כן \u0003אמר\u0004 \u0003ר' יהודה הנחתום: מעשה ואירע הדבר\u0004 הזה \u0003בבת אחותי\u0004 שהיתה \u0003כלה, ובא מעשה לפני חכמים ואמרו: תקרע כתובתה ותעמוד על מתנתה, ונמצאת קרחת מכאן ומכאן.\u0004","ונדייק: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 \u0003יצא עליו שטר חוב\u0004 יהא הדין כן, \u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003לא יצא עליו שטר חוב\u0004 — \u0003קניא\u0004 \u0005[קונה\u0006 היא\u0005]\u0006 את מה שכתב לה במתנה. ונברר: \u0003ובמאי\u0004 \u0005[במה]\u0006 מדובר כאן? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003בשכיב מרע\u0004 — \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמרת\u0004 לעיל כי שכיב מרע שכתב כל נכסיו לאשתו \u0003לא עשאה אלא אפוטרופוס\u0004 ולא קנתה דבר! \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 מדובר \u0003בבריא.\u0004 ומכאן נמצאה תשובה לשאלה ששאל רבא, שבריא שכתב כל נכסיו לאשתו — קנתה האשה.","ודוחים: \u0003לעולם\u0004 מדובר כאן \u0003בשכיב מרע, ורב עוירא מוקי לה בכולהו\u0004 \u0005[מעמיד אותה,\u0006 את ההלכה הזו, \u0005בכולם],\u0006 בכל המקרים האמורים לעיל, בהם לדעתו קונה האשה את הנכסים ואינה נעשית אפוטרופוס, ואילו \u0003רבינא מוקי לה\u0004 \u0005[מעמיד אותה]\u0006 כשיטתו שם, \u0003ב\u0004כותב כל נכסיו ל\u0003אשתו ארוסה ואשתו גרושה\u0004 שהן קונות.","אגב שהוזכרה ברייתא זו, מביאים את מה ש\u0003אמר רב יוסף בר מניומי אמר רב נחמן: הלכה\u0004 היא כדעת חכמים ש\u0003תקרע כתובתה ותעמוד על מתנתה, ונמצאת קרחת מכאן ומכאן.\u0004","ושואלים: \u0003למימרא\u0004 \u0005[האם לומר]\u0006 וללמוד מפסק זה, שככלל \u0003לא אזיל\u0004 \u0005[הולך]\u0006 \u0003רב נחמן בתר אומדנא\u0004 \u0005[אחר אומדן\u0006 דעת\u0005]?\u0006 שהרי בוודאי לא לכך התכוונה האשה כשמחלה על כתובתה, שלא תקבל דבר.","\u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003הרי שהלך בנו למדינת הים\u0004 ולא חזר, \u0003ושמע שמת בנו, ועמד וכתב כל נכסיו לאחרים, ואחר כך בא בנו\u0004 — \u0003מתנתו\u0004 שנתן לאחרים — \u0003מתנה.\u0004 \u0003ר' שמעון בן מנסיא אומר: אין מתנתו מתנה,\u0004 ומדוע? — שאומדים אנו את דעתו של הנותן, \u0003שאילו היה יודע שבנו קיים לא כתבן\u0004 את נכסיו לאחרים. \u0003ואמר רב נחמן: הלכה כר' שמעון בן מנסיא.\u0004 ומכאן רואים שרב נחמן הולך אחר אומדן דעת הנותן, ואין מתנתו מתנה!","ומשיבים: \u0003שאני התם\u0004 \u0005[שונה שם]\u0006 בענין כותב נכסיו לאשתו, שאומדים אנו את דעתה \u0003דניחא\u0004 \u0005[שנוח]\u0006 \u0003לה דתיפוק עלה קלא דכתבינהו ניהלה להנהו\u0004 \u0005[שיצא עליה קול שכתב לה את כל אותם]\u0006 \u0003נכסים,\u0004 לכן היא מסכימה לבטל את זכותה לכתובתה מכוח מתנה זו.","ומביאים הלכה נוספת בענין מתנת שכיב מרע, שגם עליה שואל רבא מה יהא הדין בבריא. \u0003תנן התם\u0004 \u0005[שנינו שם]\u0006 במשנה במסכת פאה: \u0003הכותב נכסיו לבניו, וכתב לאשתו קרקע כל שהוא\u0004 — \u0003אבדה\u0004 את זכותה לגבות \u0003כתובתה\u0004 ממה שקבלו הבנים, כפי שיכולה היתה לעשות אלמלא היה כותב לה קרקע זו. ותוהים על כך: \u0003משום\u0004 ש\u0003כתב לה קרקע כל שהוא,\u0004 לכן \u0003אבדה כתובתה?\u0004","\u0003אמר רב:\u0004 מדובר שם \u0003ב\u0004אב ה\u0003מזכה להן\u0004 לבניו את נכסיו \u0003על ידה\u0004 באמצעות אשתו. וכיון שמזכה להם על ידה והיא לא מחתה, משמע שגם היא מסכימה לכך. \u0003ושמואל אמר:\u0004 מדובר לא רק במזכה על ידה ממש, אלא אף \u0003במחלק לפניה\u0004 (בנוכחותה) את הנכסים בין הבנים \u0003והיא שותקת\u0004 ואינה שואלת \"מה יהיה בחלקי\"? ואילו \u0003ר' יוסי בר' חנינא אמר:\u0004 מדובר \u0003באומר לה \"טלי קרקע זו בכתובתך\",\u0004 כלומר, שקרקע זו תשמש עבור פרעון כל כתובתך."],["\u0003ומקולי כתובה שנו כאן,\u0004 כלומר, דבר זה, כשהאשה מאבדת באופן זה את זכותה לגבות כתובתה מנכסים, הוא מההקלות שיש בכתובה. שאין בעלי חוב רגילים מאבדים את חובם באופן זה.","ומקשים: \u0003תנן\u0004 \u0005[שנינו\u0006 באותה משנה\u0005],\u0006 \u0003ר' יוסי אומר: אם קבלה עליה\u0004 את חלוקת הנכסים הזו, \u0003אף על פי שלא כתב לה\u0004 כלשהו מנכסיו — \u0003אבדה כתובתה; מכלל\u0004 הדברים אתה למד שה\u0003תנא קמא סבר\u0004 \u0005[הראשון\u0006 שהלכה כמותו \u0005סבור]\u0006 שגם \u0003כתיבה ו\u0004גם \u0003קבלה\u0004 עליה \u0003בעי\u0004 \u0005[צריך],\u0006 בניגוד לדעת כולם — רב, שמואל ור' יוסי בר' חנינא, שדי להם בשתיקתה!","\u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 כל המשנה \u0003כולה\u0004 שיטת \u0003ר' יוסי היא\u0004 ודי לדעתו כשכתב לה או אף כשרק קיבלה עליה, \u0003והא תניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005],\u0006 \u0003אמר\u0004 \u0003ר' יהודה,\u0004 בפירוש דברי התנא הראשון: \u0003אימתי\u0004 איבדה כתובתה כשכתב לה? \u0003שהיתה שם וקבלה עליה, אבל\u0004 אם \u0003היתה שם ולא קבלה עליה,\u0004 או ש\u0003קבלה עליה ולא היתה שם\u0004 — \u0003לא אבדה כתובתה!\u0004 ואומרים: \u0003תיובתא דכולהו\u0004 \u0005[קושיה חמורה\u0006 היא \u0005על כולם]!\u0006 ומסכמים: אכן \u0003תיובתא\u0004 \u0005[קושיה חמורה\u0006 היא\u0005]\u0006 ונדחו דבריהם.","כהמשך לדברים אלו, מסופר, \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא לרב נחמן: הא\u0004 \u0005[הרי]\u0006 שיטת \u0003רב, הא\u0004 \u0005[הרי]\u0006 שיטת \u0003שמואל, הא\u0004 \u0005[הרי]\u0006 שיטת \u0003ר' יוסי בר' חנינא, מר מאי סבירא ליה\u0004 \u0005[אדוני מה סבור הוא]\u0006 בהלכה זו? \u0003אמר ליה\u0004 \u0005[לו],\u0006 \u0003שאני אומר: כיון שעשאה שותף בין הבנים\u0004 — \u0003אבדה כתובתה.\u0004","ומעירים: \u0003איתמר נמי\u0004 \u0005[נאמר גם כן]\u0006 דבר זה בשם רב נחמן באופן אחר, כפסק הלכה: \u0003אמר רב יוסף בר מניומי אמר רב נחמן:\u0004 \u0003כיון שעשאה\u0004 לאשתו \u0003שותף בין הבנים\u0004 — \u0003אבדה כתובתה.\u0004","ובענין זה \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבא: בבריא היאך\u0004 הדין? וצדדי השאלה: \u0003מי אמרינן\u0004 \u0005[האם אומרים אנו]\u0006 כי דווקא \u0003בשכיב מרע\u0004 (גוסס) כך \u0003הוא\u0004 הדין, שכיון \u0003דידעה דלית ליה\u0004 \u0005[שיודעת שאין לו]\u0006 נכסים אלא אלה, ולא יקנה עוד אחרים, \u0003ו\u0004למרות זאת אינה מוחה — יש להניח שהיא \u0003קמחלה\u0004 \u0005[מוחלת]\u0006 לו, \u0003אבל בבריא\u0004 — \u0003סברה הדר קני\u0004 \u0005[סבורה היא\u0006 ש\u0005יחזור ויקנה\u0006 נכסים\u0005]\u0006 ואותם הנכסים ישמשו לכתובתה, ולכן היא שותקת. ואין לומר שהיא מוחלת על כתובתה. \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003השתא מיהת לית ליה\u0004 \u0005[עכשיו על כל פנים אין לו]\u0006 דבר שתוכל לגבות ממנו, ואם אין היא מוחה משמע שהיא מוחלת. לשאלה זו לא נמצאה תשובה, ועל כן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","ובקשר להלכה זו, שהכותב נכסיו לבניו וכתב לאשתו חלק כלשהו בקרקע — איבדה כתובתה, מסופר, \u0003ההוא\u0004 \u0005[\u0006אדם \u0005אחד,\u0006 שכיב מרע\u0005]\u0006 ש\u0003אמר להו\u0004 \u0005[להם]\u0006 לעומדים סביבו: \u0003פלגא לברת, ופלגא לברת, ותילתא לאיתת בפירי\u0004 \u0005[חצי לבתי, וחצי לבתי\u0006 האחרת, \u0005ושליש לאשתי בפירות].\u0006 \u0003איקלע\u0004 \u0005[נזדמן]\u0006 \u0003רב נחמן לסורא, עול לגבי\u0004 \u0005[נכנס אצל]\u0006 \u0003רב חסדא, אמר ליה\u0004 \u0005[לו]\u0006 רב חסדא: \u0003כי האי גוונא מאי\u0004 \u0005[כגון זה מהו]?\u0006 מה עושים במקרה כזה? \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן, \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר שמואל: אפילו לא הקנה לה\u0004 לאשתו \u0003אלא דקל אחד ל\u0004שם \u0003פירותיו\u0004 — \u0003אבדה\u0004 על ידי כך \u0003כתובתה.\u0004","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אימור\u0004 \u0005[אמור]\u0006 ש\u0003אמר שמואל התם\u0004 \u0005[שם]\u0006 בזמן שהקנה לה דקל לפירותיו — \u0003דאקני\u0004 \u0005[שהקנה]\u0006 \u0003לה\u0004 על כל פנים זכות \u0003בגופה דארעא\u0004 \u0005[של קרקע]\u0006 שהרי הדקל מחובר לקרקע, \u0003הכא פירא הוא\u0004 \u0005[כאן\u0006 רק \u0005פירות הם]\u0006 שהקנה לה, ולא דבר בקרקע! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מטלטלי קא אמרת\u0004 \u0005[\u0006פירות \u0005מיטלטלים אמרת]?\u0006 על \u0003מטלטלי\u0004 \u0005[ מיטלטלים ]\u0006 \u0003ודאי לא קא אמינא\u0004 \u0005[איני אומר]\u0006 הלכה זו, וגובה כתובתה.","ועוד מסופר בענין דומה, \u0003ההוא\u0004 \u0005[\u0006אדם \u0005אחד]\u0006 ש\u0003אמר להו\u0004 \u0005[להם]\u0006 בשעת מותו: \u0003תלתא לברת, ותלתא לברת, ותלתא לאיתת\u0004 \u0005[שליש לבת, ושליש לבת\u0006 אחרת, \u0005ושליש לאשה].\u0006 \u0003שכיבא חדא מבנתיה\u0004 \u0005[מתה אחת מבנותיו]\u0006 בחייו, וחזר חלקה לידי אביה. \u0003סבר רב פפי למימר\u0004 \u0005[לומר]:\u0006 האשה \u0003לא שקלא\u0004 \u0005[מקבלת]\u0006 \u0003אלא תלתא\u0004 \u0005[שליש],\u0006 ואינה גובה כתובתה עוד מן הנכסים שירשו הבנות. שהרי משעה שנתן לה קרקע ועשאה שותפה עם הבנות — כבר ויתרה על כתובתה,"],["\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב כהנא: אילו הדר קני\u0004 \u0005[היה חוזר\u0006 ו\u0005קונה]\u0006 נכסים אחרים, \u0003מי\u0004 \u0005[האם]\u0006 \u0003לא שקלא\u0004 \u0005[היתה נוטלת]\u0006 כתובתה מאותם נכסים? \u0003וכיון\u0004 ש\u0003אילו הדר קני שקלא\u0004 \u0005[היה חוזר\u0006 ו\u0005קונה היתה נוטלת],\u0006 \u0003השתא נמי שקלא\u0004 \u0005[עכשיו גם כן נוטלת]\u0006 כתובתה מחלק הבת שמתה.","ועוד בענין זה, מסופר, \u0003ההוא דפלגינהו לנכסיה לאתתיה ולבניה\u0004 \u0005[\u0006אדם \u0005אחד שחילק את נכסיו לאשתו ולבניו],\u0006 שעשאה שותף בין בניו, \u0003שייר חד דיקלא\u0004 \u0005[דקל אחד]\u0006 שלא כתב למי הוא שייך, \u0003סבר\u0004 \u0005[סבור\u0006 היה\u0005]\u0006 \u0003רבינא למימר\u0004 \u0005[לומר]\u0006 כי \u0003לית\u0004 \u0005[אין]\u0006 \u0003לה\u0004 לצורך גביית כתובתה \u0003אלא חד דיקלא\u0004 \u0005[דקל אחד].\u0006 שכיון שהשאיר לה דקל אחד שלא פירש, מן הסתם אותו ייחד לשם כתובתה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב יימר לרבינא: אי לית\u0004 \u0005[אם אין]\u0006 \u0003לה\u0004 זכות לגבות כתובתה בשאר הנכסים, שאתה סבור שויתרה לגמרי על כתובתה — \u0003חד דיקלא נמי לית\u0004 \u0005[\u0006אותו \u0005דקל אחד גם כן אין]\u0006 \u0003לה,\u0004 והוא של היורשים! \u0003אלא,\u0004 כך צריך אתה לומר: \u0003מיגו דנחתא לדיקלא\u0004 \u0005[מתוך ש\u0006היא \u0005יורדת\u0006 ונוטלת \u0005את הדקל\u0006 בכתובתה\u0005],\u0006 ומכאן עולה שלא איבדה אותה — \u0003נחתא נמי לכולהו נכסי\u0004 \u0005[יורדת גם כן לכל הנכסים]\u0006 לגבות מהם.","ועוד לענין המשנה, \u0003אמר רב הונא: שכיב מרע שכתב כל נכסיו לאחר\u0004 — \u0003רואין: אם\u0004 אותו אדם \u0003ראוי ליורשו,\u0004 כגון אחד מבניו — \u0003נוטלן משום ירושה, ואם לאו\u0004 \u0005[לא]\u0006 — \u0003נוטלן משום מתנה.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב נחמן: גנבא גנובי\u0004 \u0005[גנוב לגנוב]\u0006 \u0003למה לך,\u0004 לומר כך את דבריך? \u0003אי סבירא לך\u0004 \u0005[אם סבור אתה]\u0006 \u0003כר' יוחנן בן ברוקה, אימא\u0004 \u0005[אמור]\u0006 במפורש: \u0003הלכה כר' יוחנן בן ברוקה, דהא שמעתתיך\u0004 \u0005[שהרי ההלכה שלך]\u0006 \u0003כר' יוחנן בן ברוקה הוא דאזלא\u0004 \u0005[שהולכת],\u0006 שיכול אדם להוריש את כל נכסיו לכל מי שירצה מיורשיו!","\u0003דלמא כי הא קאמרת\u0004 \u0005[שמא\u0006 במקרה \u0005כגון זה אומר אתה,\u0006 מתכוון אתה בדבריך\u0005]:\u0006 \u0003דההוא דהוה קא שכיב\u0004 \u0005[\u0006במקרה \u0005של\u0006 אדם \u0005אחד שהיה גוסס]\u0006 ולא היו לו בנים, \u0003ואמרו ליה\u0004 \u0005[לו]:\u0006 \u0003נכסיה למאן\u0004 \u0005[הנכסים למי],\u0006 \u0003דלמא לפלניא\u0004 \u0005[שמא לפלוני]?\u0006 \u0003ואמר להו\u0004 \u0005[להם]:\u0006 \u0003אלא למאן\u0004 \u0005[למי]?\u0006 \u0003ואמרת לן עלה\u0004 \u0005[לנו עליה]:\u0006 \u0003אם\u0004 אותו פלוני \u0003ראוי ליורשו\u0004 — \u0003נוטלן משום ירושה, ואם לאו\u0004 \u0005[לא]\u0006 — \u0003נוטלן משום מתנה? אמר ליה\u0004 \u0005[לו]\u0006 רב הונא לרב נחמן: \u0003אין, הכי קאמינא\u0004 \u0005[כן, כך\u0006 אמנם \u0005אני אומר],\u0006 כלומר, זו היתה כוונת דבריי.","ושואלים: \u0003למאי הלכתא\u0004 \u0005[למה,\u0006 לאיזו \u0005הלכה]\u0006 נחוצה הבחנה זו בין ירושה ומתנה? והרי בין כה וכה הנכסים מגיעים לידי אותו אדם, ומה ההבדל אם נוטלם משום ירושה או משום מתנה? \u0003סבר\u0004 \u0005[סבור\u0006 היה\u0005]\u0006 \u0003רב אדא בר אהבה\u0004 כאשר ישב \u0003קמיה\u0004 \u0005[לפני]\u0006 \u0003רבא למימר\u0004 \u0005[לומר]\u0006 כך: \u0003אם ראוי\u0004 אותו אדם \u0003ליורשו\u0004 — \u0003אלמנתו\u0004 של המוריש \u0003נזונית מנכסיו,\u0004 שהרי לאלמנה יש זכות למזונות מן הנכסים שבידי היורשים, \u0003ואם לאו\u0004 \u0005[לא],\u0006 שאינו ראוי ליורשו, ונכסים אלו ניתנו לו במתנה — \u0003אין אלמנתו נזונית מנכסיו.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא:\u0004 וכי \u0003מיגרע גרעא\u0004 \u0005[נגרע]\u0006 כוחה של האלמנה אם היתה זו מתנה? \u0003השתא\u0004 \u0005[עכשיו\u0006 הרי\u0005]\u0006 \u0003בירושה\u0004 שהיא \u0003דאורייתא\u0004 \u0005[מן התורה]\u0006 \u0003אמרת\u0004 \u0005[אומר אתה]\u0006 ש\u0003אלמנתו נזונית מנכסיו, במתנה\u0004 מתנת שכיב מרע, שאינה נקנית למקבל אלא \u0003דרבנן\u0004 \u0005[מדברי סופרים],\u0006 \u0003לא כל שכן\u0004 שאשתו ניזונת מהם?","\u0003אלא אמר רבא:\u0004 חשיבותה של ההבחנה בין מתנה לירושה הריהי כמו ש\u0003שלח רב אחא בר רב עויא: לדברי\u0004 \u0003ר' יוחנן בן ברוקה,\u0004 אם אמר \u0003\"נכסי לך ואחריך לפלוני\", אם היה ראשון ראוי ליורשו\u0004 — \u0003אין לשני במקום ראשון כלום, ש\u0004במקרה כזה שהוא ראוי ליורשו \u0003אין\u0004 לשון זו (\"נכסי לך\") \u0003לשון מתנה אלא לשון ירושה, וירושה אין לה הפסק,\u0004 לא ניתן לקטוע אותה, והיא עוברת מאליה מאדם ליורשיו. ולפי זה אם ירושה היתה לראשון — שוב אין מוציאים מידו ומיד יורשיו אחריו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא לרב נחמן:\u0004 איך אנו יכולים לומר שנתינה זו אין לה הפסק? \u0003והא אפסקה\u0004 \u0005[והרי הפסיק אותה\u0006 הוא עצמו\u0005]\u0006 שהרי אמר \"אחריך לפלוני\"! ואומרים: אכן \u0003הוא\u0004 המוריש \u0003סבר\u0004 \u0005[סבור]\u0006 שירושה \u0003יש לה הפסק,\u0004 ולכן נתנה לאחר, \u0003ו\u0004אולם \u0003רחמנא אמר\u0004 \u0005[התורה אמרה]:\u0006 \u0003אין לה הפסק\u0004 ודבריו בטלים."],["ומסופר: \u0003ההוא\u0004 \u0005[\u0006אדם \u0005אחד]\u0006 ש\u0003אמר ליה לחבריה\u0004 \u0005[לו לחבירו]:\u0006 \u0003\"נכסי לך ואחריך לפלוני\", ו\u0004ה\u0003ראשון ראוי ליורשו הוה\u0004 \u0005[היה].\u0006 \u0003שכיב\u0004 \u0005[מת]\u0006 ה\u0003ראשון, אתא\u0004 \u0005[בא]\u0006 ה\u0003שני קא תבע\u0004 \u0005[\u0006ו\u0005תבע]\u0006 את הנכסים,","\u0003סבר\u0004 \u0005[סבור\u0006 היה\u0005]\u0006 \u0003רב עיליש\u0004 כאשר ישב \u0003קמיה\u0004 \u0005[לפני]\u0006 \u0003רבא למימר\u0004 \u0005[לומר]:\u0006 \u0003שני נמי שקיל\u0004 \u0005[גם כן נוטל]\u0006 כמו יורשי הראשון, \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא: \u0003דייני דחצצתא הכי דייני\u0004 \u0005[דיינים של פשרה,\u0006 שמחלקים חצי לזה וחצי לזה, \u0005כך\u0006 הם \u0005דנים],\u0006 \u0003לאו היינו\u0004 \u0005[האם לא זהו]\u0006 ש\u0003שלח רב אחא בר רב עויא\u0004 שבמקרה זה אין השני נוטל?","\u0003אכסיף\u0004 \u0005[התבייש]\u0006 רב עיליש על שדן שלא כראוי. \u0003קרי עליה\u0004 \u0005[קרא עליו]\u0006 רבא את הפסוק \u0003\"אני ה' בעתה אחישנה\"\u0004 (ישעיהו ס, כב), כדי לנחמו, לומר: מאת ה' היתה זאת, שעוד לפני שנכשלת בדבר הייתי אני מצוי לתקן אותך.","\u0003הכותב את נכסיו לאחרים\u0004 במתנה \u0003והניח את בניו\u0004 ולא נתן להם כלום — \u0003מה שעשה עשוי, אלא\u0004 ש\u0003אין רוח חכמים נוחה הימנו\u0004 (ממנו). \u0003רבן שמעון בן גמליאל אומר: אם לא היו בניו נוהגים כשורה\u0004 ומשום כך העבירם אביהם מנכסיו ונתנם לאחרים — \u0003זכור לטוב.\u0004","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 \u0003מי פליגי רבנן עליה\u0004 \u0005[האם נחלקו חכמים עליו]\u0006 על \u0003רבן שמעון בן גמליאל,\u0004 וסבורים שבכל מקרה אין זה ראוי לאדם לכתוב נכסיו לאחרים, \u0003או לא,\u0004 ובמקרה של בנים שאינם הגונים גם הם מסכימים עמו?","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו: \u0003יוסף בן יועזר היה לו בן שלא היה נוהג כשורה, הוה ליה עיליתא דדינרי\u0004 \u0005[היה לו\u0006 בנכסיו \u0005כלי מלא דינרים],\u0006 \u0003קם אקדשה\u0004 \u0005[עמד\u0006 ו\u0005הקדיש אותה]\u0006 את הכלי למקדש. \u0003אזיל נסיב\u0004 \u0005[הלך\u0006 הבן ו\u0005נשא]\u0006 \u0003בת\u0004 של \u0003גאדיל כלילי\u0004 \u0005[קושר הכתרים]\u0006 של \u0003ינאי מלכא\u0004 \u0005[המלך],\u0006 \u0003אולידה דביתהו\u0004 \u0005[ילדה אשתו],\u0006 \u0003זבין\u0004 \u0005[קנה]\u0006 \u0003לה ביניתא\u0004 \u0005[דג].\u0006 \u0003קרעה\u0004 את בטנו של הדג, \u0003אשכח\u0004 \u0005[מצא]\u0006 \u0003בה מרגליתא\u0004 \u0005[מרגלית]\u0006 ורצה למוכרה כדי לקבל כסף עבורה.","\u0003אמרה ליה\u0004 \u0005[לו]\u0006 אשתו: \u0003לא תמטייה למלכא\u0004 \u0005[אל תביא אותה ל\u0006בית ה\u0005מלך\u0006 שיקנו אותה\u0005],\u0006 משום \u0003דשקלי לה מינך בדמי קלילי\u0004 \u0005[שיקחו אותה ממך בכסף מועט],\u0006 \u0003זיל אמטייה לגבי גזברי\u0004 \u0005[לך הבא אותה אצל הגזברים]\u0006 של בית המקדש שיקנו אותה. \u0003ו\u0004כשתביא אותה אליהם \u0003לא תשיימה את\u0004 \u0005[אל תשום,\u0006 תעריך \u0005אותה אתה]\u0006 לומר מהו מחירה, לפי ש\u0003אמירתו לגבוה כמסירתו להדיוט,\u0004 ואם תאמר סכום פחות — יתפסו אותך בדבריך ובכך תישאר, \u0003אלא לשיימוה אינהו\u0004 \u0005[שישומו אותה הם].\u0006","עשה כדבריה, \u0003אמטייה\u0004 \u0005[הביאה]\u0006 את המרגלית לגזבר בית המקדש, \u0003שמוה בתליסרי עליאתא דדינרי\u0004 \u0005[העריכו אותה בשלושה עשר\u0006 \u0005כלים של דינרים].\u0006 \u0003אמרי ליה\u0004 \u0005[אמרו לו]:\u0006 \u0003שבע איכא\u0004 \u0005[יש\u0006 בידינו\u0005]\u0006 כדי לשלם לך עבור המרגלית, \u0003שית ליכא\u0004 \u0005[שש\u0006 נוספות \u0005אין]\u0006 בידינו. \u0003אמר להו\u0004 \u0005[להם]\u0006 לגזברים: \u0003שבע הבו\u0004 \u0005[תנו]\u0006 \u0003לי\u0004 תמורתה, \u0003שית\u0004 \u0005[שש]\u0006 הנוספות שאתם חייבים לי \u0003הרי הן מוקדשות לשמים.\u0004","\u0003עמדו וכתבו\u0004 בלשון שבח: \u0003יוסף בן יועזר הכניס\u0004 לקופת ההקדש \u0003אחת, ובנו הכניס שש. ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 שכתבו כך ובלשון של גנאי: \u0003יוסף בן יועזר הכניס\u0004 לקופת ההקדש \u0003אחת, ובנו הוציא\u0004 ממנה \u0003שבע\u0004 שקיבל עבור המרגלית.","ומעירים: \u0003מדקא אמרי\u0004 \u0005[מכיון שאמרו]\u0006 לגבי בנו של יוסף בן יועזר \u0003\"הכניס\",\u0004 בלשון שבח, \u0003מכלל דשפיר עבד\u0004 \u0005[מכאן שיפה עשה]\u0006 שלא הוריש לבנו. ואומרים: \u0003אדרבה\u0004 \u0005[להיפך],\u0006 \u0003מדקא אמרי\u0004 \u0005[ממה שאמרו]\u0006 בלשון השניה על בנו \u0003\"הוציא\", מכלל דלאו שפיר עבד\u0004 \u0005[שלא יפה עשה]\u0006 האב שלא הוריש לבנו, ולכן גרם שיצא הכסף מן ההקדש על ידי בנו! \u0003אלא מהא ליכא למשמע מינה\u0004 \u0005[מ\u0006מעשה \u0005זה אין לשמוע]\u0006 להוכיח דבר לגבי השאלה האם חכמים מודים לרבן שמעון בן גמליאל.","ושואלים: \u0003מאי הוי עלה\u0004 \u0005[מה היה עליה]\u0006 על בעיה זו? כיצד פתרו אותה? \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע],\u0006 ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003שמואל לרב יהודה: שיננא\u0004 \u0005[גדול השיניים],\u0006 \u0003לא תיהוי בי עבורי אחסנתא\u0004 \u0005[אל תהיה\u0006 במקום \u0005בו מעבירים ירושה]\u0006 מן הזכאי לה, \u0003ואפילו\u0004 כשמעבירים \u0003מברא בישא לברא טבא\u0004 \u0005[מבן רע לבן טוב],\u0006 \u0003וכל שכן\u0004 כשמעבירים \u0003מברא לברתא\u0004 \u0005[מבן לבת].\u0006 הרי שאין חכמים מודים כלל לרבן שמעון בן גמליאל.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מעשה באדם אחד שלא היו בניו נוהגין כשורה, עמד וכתב\u0004 כל \u0003נכסיו\u0004 במתנה \u0003ליונתן בן עוזיאל. מה עשה יונתן בן עוזיאל? מכר שליש\u0004 הנכסים לצרכיו, \u0003והקדיש שליש\u0004 הנכסים, \u0003והחזיר לבניו\u0004 של אותו אדם \u0003שליש\u0004 הנכסים.","\u0003בא עליו שמאי במקלו ותרמילו\u0004 להתרעם על שעשה שלא כדעת הנותן, ונתן חלק לבנים. \u0003אמר לו\u0004 יונתן בן עוזיאל: \u0003שמאי, אם אתה יכול להוציא\u0004 מידי המקבלים \u0003את מה שמכרתי ומה שהקדשתי\u0004 מן הנכסים — \u0003אתה יכול להוציא\u0004 גם את \u0003מה שהחזרתי\u0004 לבנים,"]]};
